1	/**
2	 * Geometry Admin Router — tRPC endpoints for the /admin/geometry dashboard.
3	 * 
4	 * Provides real-time and historical data for emotional geometry monitoring:
5	 * - Session listing with aggregate metrics
6	 * - Snapshot timeseries for longitudinal analysis
7	 * - Event timeline for alerts and interventions
8	 * - Live state from the runtime bridge
9	 * - Prometheus-style metrics export
10	 */
11	
12	import { z } from 'zod';
13	import { TRPCError } from '@trpc/server';
14	import { createLogger } from '../_core/logger';
15	
16	const log = createLogger('geometry-admin-router');
17	import { adminProcedure, router } from '../_core/trpc';
18	import { getDb } from '../db';
19	import { geometrySessions, geometrySnapshots, geometryEvents } from '../../drizzle/schema';
20	import { desc, eq, and, gte, count, avg, max, sql } from 'drizzle-orm';
21	import { createSafeDefaults, preGenerationHook, postGenerationHook } from '../emotional-geometry-runtime/geometry-runtime-bridge';
22	import { getGeometryMetrics, resetGeometryMetrics, recordPreHook, recordPostHook } from '../emotional-geometry-runtime/geometry-metrics';
23	import { getFlags, getRuntimeMode, setGeometryFlag, setGeometryRuntimeMode, type GeometryFeatureFlags, type GeometryRuntimeMode } from '../emotional-geometry-runtime/feature-flags';
24	import { advancedPreGenerationHook, advancedPostGenerationHook } from '../neurocosmology-runtime-advanced/integration-hooks';
25	import { getAdvancedFlagDiagnostics, getAdvancedFlags, getAdvancedRuntimeMode, setAdvancedFlag, setAdvancedRuntimeMode, type AdvancedFeatureFlags, type AdvancedRuntimeMode } from '../neurocosmology-runtime-advanced/feature-flags';
26	import { getAlertConfigs, getAlertConfig, setAlertThreshold, setAlertEnabled, setAlertCooldown, setAlertSeverity, resetAlertConfigs, getAlertHistory, getAlertHistoryFromDb, acknowledgeAlert, acknowledgeAlertPersistent, getAlertSummary, getUnacknowledgedCount, getNotificationChannels, createNotificationChannel, updateNotificationChannel, deleteNotificationChannel, evaluateAlerts, ALERT_TYPES, type AlertType, type AlertSeverity } from '../emotional-geometry-runtime/geometry-alerting';
27	import { getEscalationPolicies, createEscalationPolicy, updateEscalationPolicy, deleteEscalationPolicy, getEscalationHistory, runEscalationCheck, isEscalationEngineRunning, getSSEClientCount, type EscalationPolicyConfig } from '../emotional-geometry-runtime/escalation-engine';
28	import { getAlertFrequencyByType, getAlertSummaryStats, getIncidents, getIncidentDetail, resolveIncident, acknowledgeIncident } from '../emotional-geometry-runtime/alert-analytics';
29	
30	export const geometryAdminRouter = router({
31	  // =========================================================================
32	  // NEUROCOSMOLOGY VALIDATION ENDPOINTS
33	  // =========================================================================
34	
35	  /**
36	   * Get neurocosmology validation status — calibration state, recent runs,
37	   * proof bundles, registered backends.
38	   * Exposed at /admin/neurocosmology in the dashboard.
39	   */
40	  neurocosmologyStatus: adminProcedure
41	    .query(async () => {
42	      const { getNeurocosmologyStatus } = await import(
43	        '../emotional-geometry-runtime/validation/validationOrchestrator'
44	      );
45	      return getNeurocosmologyStatus();
46	    }),
47	
48	  /**
49	   * Trigger a validation run (on-demand, not just nightly).
50	   * Requires at least 2 model backends configured via env vars.
51	   */
52	  triggerValidation: adminProcedure
53	    .input(z.object({
54	      modelIds: z.array(z.string()).optional(),
55	      stimuliSubset: z.array(z.string()).optional(),
56	      skipHumanCalibration: z.boolean().optional(),
57	    }).optional())
58	    .mutation(async ({ input }) => {
59	      const { runValidation } = await import(
60	        '../emotional-geometry-runtime/validation/validationOrchestrator'
61	      );
62	      return runValidation(input ?? undefined);
63	    }),
64	
65	  /**
66	   * Get current calibration state (hot-path, in-memory).
67	   */
68	  calibrationState: adminProcedure
69	    .query(async () => {
70	      const { getCalibrationState } = await import(
71	        '../emotional-geometry-runtime/validation/calibrationMode'
72	      );
73	      return getCalibrationState();
74	    }),
75	
76	  /**
77	   * Check whether field-driven boosts are currently active.
78	   */
79	  fieldBoostsActive: adminProcedure
80	    .query(async () => {
81	      const { areFieldBoostsActive } = await import(
82	        '../emotional-geometry-runtime/validation/calibrationMode'
83	      );
84	      return { active: areFieldBoostsActive() };
85	    }),
86	
87	  /**
88	   * Get recent proof bundles for provenance audit.
89	   */
90	  proofBundles: adminProcedure
91	    .input(z.object({ limit: z.number().min(1).max(100).default(10) }).optional())
92	    .query(async ({ input }) => {
93	      const { getRecentProofBundles } = await import(
94	        '../emotional-geometry-runtime/validation/calibrationMode'
95	      );
96	      return getRecentProofBundles(input?.limit ?? 10);
97	    }),
98	
99	  // =========================================================================
100	  // ORIGINAL GEOMETRY ADMIN ENDPOINTS
101	  // =========================================================================
102	
103	  /**
104	   * Get overview stats for the geometry dashboard header cards.
105	   */
106	  getOverview: adminProcedure
107	    .input(z.object({
108	      timeRangeHours: z.number().min(1).max(720).default(24),
109	    }).optional())
110	    .query(async ({ input }) => {
111	      const db = await getDb();
112	      const hours = input?.timeRangeHours ?? 24;
113	      const since = new Date(Date.now() - hours * 60 * 60 * 1000);
114	
115	      const [sessionStats] = await db
116	        .select({
117	          totalSessions: count(),
118	          avgFixation: avg(geometrySessions.avgFixationRisk),
119	          avgDrift: avg(geometrySessions.avgDriftScore),
120	          maxFixation: max(geometrySessions.maxFixationRisk),
121	          maxDrift: max(geometrySessions.maxDriftScore),
122	          avgCompute: avg(geometrySessions.avgComputeTimeMs),
123	        })
124	        .from(geometrySessions)
125	        .where(gte(geometrySessions.createdAt, since));
126	
127	      const [snapshotStats] = await db
128	        .select({
129	          totalGenerations: count(),
130	          constraintsInjected: sql<number>`SUM(CASE WHEN ${geometrySnapshots.shouldConstrain} = true THEN 1 ELSE 0 END)`,
131	          loopsDetected: sql<number>`SUM(CASE WHEN ${geometrySnapshots.loopDetected} = true THEN 1 ELSE 0 END)`,
132	          singularities: sql<number>`SUM(CASE WHEN ${geometrySnapshots.singularityDetected} = true THEN 1 ELSE 0 END)`,
133	          phaseTransitions: sql<number>`SUM(CASE WHEN ${geometrySnapshots.phaseTransitionDetected} = true THEN 1 ELSE 0 END)`,
134	        })
135	        .from(geometrySnapshots)
136	        .where(gte(geometrySnapshots.createdAt, since));
137	
138	      const [eventStats] = await db
139	        .select({
140	          totalEvents: count(),
141	          criticalEvents: sql<number>`SUM(CASE WHEN ${geometryEvents.severity} = 'critical' THEN 1 ELSE 0 END)`,
142	          warningEvents: sql<number>`SUM(CASE WHEN ${geometryEvents.severity} = 'warning' THEN 1 ELSE 0 END)`,
143	        })
144	        .from(geometryEvents)
145	        .where(gte(geometryEvents.createdAt, since));
146	
147	      return {
148	        timeRangeHours: hours,
149	        sessions: {
150	          total: sessionStats?.totalSessions ?? 0,
151	          avgFixationRisk: Number(sessionStats?.avgFixation ?? 0),
152	          avgDriftScore: Number(sessionStats?.avgDrift ?? 0),
153	          maxFixationRisk: Number(sessionStats?.maxFixation ?? 0),
154	          maxDriftScore: Number(sessionStats?.maxDrift ?? 0),
155	          avgComputeTimeMs: Number(sessionStats?.avgCompute ?? 0),
156	        },
157	        generations: {
158	          total: snapshotStats?.totalGenerations ?? 0,
159	          constraintsInjected: Number(snapshotStats?.constraintsInjected ?? 0),
160	          loopsDetected: Number(snapshotStats?.loopsDetected ?? 0),
161	          singularities: Number(snapshotStats?.singularities ?? 0),
162	          phaseTransitions: Number(snapshotStats?.phaseTransitions ?? 0),
163	        },
164	        events: {
165	          total: eventStats?.totalEvents ?? 0,
166	          critical: Number(eventStats?.criticalEvents ?? 0),
167	          warnings: Number(eventStats?.warningEvents ?? 0),
168	        },
169	        metrics: getGeometryMetrics(),
170	      };
171	    }),
172	
173	  /**
174	   * List geometry sessions with pagination.
175	   */
176	  listSessions: adminProcedure
177	    .input(z.object({
178	      limit: z.number().min(1).max(100).default(20),
179	      offset: z.number().min(0).default(0),
180	      status: z.enum(["active", "completed", "error"]).optional(),
181	    }).optional())
182	    .query(async ({ input }) => {
183	      const db = await getDb();
184	      const limit = input?.limit ?? 20;
185	      const offset = input?.offset ?? 0;
186	      const status = input?.status;
187	
188	      const conditions = status ? [eq(geometrySessions.status, status)] : [];
189	
190	      const sessions = await db
191	        .select()
192	        .from(geometrySessions)
193	        .where(conditions.length > 0 ? and(...conditions) : undefined)
194	        .orderBy(desc(geometrySessions.createdAt))
195	        .limit(limit)
196	        .offset(offset);
197	
198	      const [{ total }] = await db
199	        .select({ total: count() })
200	        .from(geometrySessions)
201	        .where(conditions.length > 0 ? and(...conditions) : undefined);
202	
203	      return { sessions, total, limit, offset };
204	    }),
205	
206	  /**
207	   * Get snapshots for a specific session (timeseries data).
208	   */
209	  getSessionSnapshots: adminProcedure
210	    .input(z.object({
211	      sessionId: z.string(),
212	      limit: z.number().min(1).max(500).default(100),
213	    }))
214	    .query(async ({ input }) => {
215	      const db = await getDb();
216	      const snapshots = await db
217	        .select()
218	        .from(geometrySnapshots)
219	        .where(eq(geometrySnapshots.sessionId, input.sessionId))
220	        .orderBy(geometrySnapshots.generationIndex)
221	        .limit(input.limit);
222	
223	      return { snapshots, sessionId: input.sessionId };
224	    }),
225	
226	  /**
227	   * Get event timeline with filtering.
228	   */
229	  getEvents: adminProcedure
230	    .input(z.object({
231	      limit: z.number().min(1).max(200).default(50),
232	      offset: z.number().min(0).default(0),
233	      eventType: z.string().optional(),
234	      severity: z.enum(["info", "warning", "critical"]).optional(),
235	      sessionId: z.string().optional(),
236	      timeRangeHours: z.number().min(1).max(720).default(24),
237	    }).optional())
238	    .query(async ({ input }) => {
239	      const db = await getDb();
240	      const limit = input?.limit ?? 50;
241	      const offset = input?.offset ?? 0;
242	      const since = new Date(Date.now() - (input?.timeRangeHours ?? 24) * 60 * 60 * 1000);
243	
244	      const conditions = [gte(geometryEvents.createdAt, since)];
245	      if (input?.severity) conditions.push(eq(geometryEvents.severity, input.severity));
246	      if (input?.sessionId) conditions.push(eq(geometryEvents.sessionId, input.sessionId));
247	
248	      const events = await db
249	        .select()
250	        .from(geometryEvents)
251	        .where(and(...conditions))
252	        .orderBy(desc(geometryEvents.createdAt))
253	        .limit(limit)
254	        .offset(offset);
255	
256	      const [{ total }] = await db
257	        .select({ total: count() })
258	        .from(geometryEvents)
259	        .where(and(...conditions));
260	
261	      return { events, total, limit, offset };
262	    }),
263	
264	  /**
265	   * Get the current runtime state (live, not from DB).
266	   */
267	  getLiveState: adminProcedure
268	    .query(async () => {
269	      const safeDefaults = createSafeDefaults();
270	      const metrics = getGeometryMetrics();
271	
272	      return {
273	        runtimeStatus: 'active',
274	        safeDefaults,
275	        metrics,
276	        timestamp: Date.now(),
277	      };
278	    }),
279	
280	  /**
281	   * Get Prometheus-style metrics export.
282	   */
283	  getMetrics: adminProcedure
284	    .query(async () => {
285	      return getGeometryMetrics();
286	    }),
287	
288	  /**
289	   * Reset metrics counters (admin action).
290	   */
291	  resetMetrics: adminProcedure
292	    .mutation(async () => {
293	      resetGeometryMetrics();
294	      return { success: true, resetAt: Date.now() };
295	    }),
296	
297	  /**
298	   * Get stability distribution over time (for charts).
299	   */
300	  getStabilityDistribution: adminProcedure
301	    .input(z.object({
302	      timeRangeHours: z.number().min(1).max(720).default(24),
303	    }).optional())
304	    .query(async ({ input }) => {
305	      const db = await getDb();
306	      const since = new Date(Date.now() - (input?.timeRangeHours ?? 24) * 60 * 60 * 1000);
307	
308	      const distribution = await db
309	        .select({
310	          stabilityClass: geometrySnapshots.stabilityClass,
311	          count: count(),
312	        })
313	        .from(geometrySnapshots)
314	        .where(gte(geometrySnapshots.createdAt, since))
315	        .groupBy(geometrySnapshots.stabilityClass);
316	
317	      return { distribution, timeRangeHours: input?.timeRangeHours ?? 24 };
318	    }),
319	
320	  /**
321	   * Diagnostic: trigger a live governed generation through the full geometry pipeline.
322	   * Returns the complete audit trail showing pre-hook → post-hook → metrics recording.
323	   */
324	  diagnosticGeneration: adminProcedure
325	    .input(z.object({
326	      prompt: z.string().min(1).max(500).default('What is emotional intelligence and why does it matter?'),
327	      currentState: z.record(z.number()).optional(),
328	    }).optional())
329	    .mutation(async ({ input, ctx }) => {
330	      const startTime = performance.now();
331	      const auditTrail: string[] = [];
332	      const flags = getFlags();
333	      const mode = getRuntimeMode();
334	      const advancedDiag = getAdvancedFlagDiagnostics();
335	
336	      auditTrail.push(`[CONFIG] Runtime: ${flags.GEOMETRY_RUNTIME_ENABLED ? 'ENABLED' : 'DISABLED'}, Mode: ${mode}`);
337	      auditTrail.push(`[CONFIG] Flags: ${JSON.stringify(flags)}`);
338	      auditTrail.push(`[CONFIG] Neuro advanced: ${advancedDiag.enabled ? 'ENABLED' : 'DISABLED'}, Mode: ${advancedDiag.mode}`);
339	
340	      const testState = input?.currentState ?? {
341	        emotionalMass: 5.0,
342	        emotionalCharge: 0.3,
343	        emotionalDistance: 2.0,
344	        attentionCurvature: 1.5,
345	        memoryEntropy: 0.7,
346	        emotionalEnergy: 12.5,
347	        subconscious_density: 0.4,
348	        recurrenceCount: 3,
349	        topicDiversity: 0.6,
350	        emotionalValence: 0.2,
351	        arousalLevel: 0.5,
352	        coherenceScore: 0.8,
353	      };
354	
355	      // Step 1: Pre-generation hook
356	      let preResult;
357	      try {
358	        preResult = await preGenerationHook({
359	          sessionId: `diag_${Date.now()}`,
360	          userId: `admin-${ctx.user.id}`,
361	          prompt: input?.prompt ?? 'What is emotional intelligence and why does it matter?',
362	          currentState: testState,
363	        });
364	        auditTrail.push(`[PRE-HOOK] Hash: ${preResult.preStateHash}, Fixation: ${preResult.fixationRisk.toFixed(4)}, Drift: ${preResult.driftScore.toFixed(4)}, Stability: ${preResult.stabilityClass}, Eigen: ${preResult.eigenClassification}, Constrain: ${preResult.shouldConstrain}, Time: ${preResult.computeTimeMs.toFixed(2)}ms`);
365	        if (preResult.constraintsInjected.length > 0) {
366	          auditTrail.push(`[PRE-HOOK] Constraints: ${preResult.constraintsInjected.join(', ')}`);
367	        }
368	        // Record metrics
369	        recordPreHook(preResult.fixationRisk, preResult.driftScore, preResult.computeTimeMs);
370	        auditTrail.push(`[METRICS] Pre-hook metrics recorded`);
371	      } catch (err) {
372	        auditTrail.push(`[PRE-HOOK] FAILED: ${err instanceof Error ? err.message : String(err)}`);
373	        preResult = createSafeDefaults();
374	      }
375	
376	      // Step 2: Advanced neurocosmology pre-hook
377	      try {
378	        const advPre = await advancedPreGenerationHook({
379	          currentState: testState,
380	          stateHistory: [],
381	        });
382	        if (advPre.enabled) {
383	          auditTrail.push(`[NEURO-PRE] Mode: ${advPre.mode}, Singularity: ${advPre.singularity?.isSingularity ?? false}, PhaseShift: ${advPre.phaseTransition?.isPhaseShift ?? false}, Invariants: ${advPre.invariantReport?.violations?.length ?? 0}, Time: ${advPre.computeTimeMs.toFixed(2)}ms`);
384	        } else {
385	          auditTrail.push(`[NEURO-PRE] Disabled (mode: ${advPre.mode})`);
386	        }
387	      } catch (err) {
388	        auditTrail.push(`[NEURO-PRE] FAILED (non-blocking): ${err instanceof Error ? err.message : String(err)}`);
389	      }
390	
391	      // Step 3: Simulate LLM output (we don't actually call LLM in diagnostic mode)
392	      const simulatedOutput = 'Emotional intelligence is the ability to recognize, understand, and manage our own emotions while also being able to recognize, understand, and influence the emotions of others. It matters because it affects our relationships, decision-making, and overall well-being.';
393	      auditTrail.push(`[LLM] Simulated output (${simulatedOutput.length} chars) — diagnostic mode does not call real LLM`);
394	
395	      // Step 4: Post-generation hook
396	      let postResult;
397	      try {
398	        postResult = await postGenerationHook({
399	          sessionId: `diag_${Date.now()}`,
400	          output: simulatedOutput,
401	          preResult,
402	        });
403	        auditTrail.push(`[POST-HOOK] Hash: ${postResult.postStateHash}, EntropyΔ: ${postResult.entropyDelta.toFixed(4)}, CurvatureΔ: ${postResult.curvatureDelta.toFixed(4)}, Loop: ${postResult.loopDetected}, Time: ${postResult.computeTimeMs.toFixed(2)}ms`);
404	        // Record metrics
405	        recordPostHook(postResult.loopDetected, postResult.computeTimeMs);
406	        auditTrail.push(`[METRICS] Post-hook metrics recorded`);
407	      } catch (err) {
408	        auditTrail.push(`[POST-HOOK] FAILED: ${err instanceof Error ? err.message : String(err)}`);
409	      }
410	
411	      // Step 5: Advanced neurocosmology post-hook
412	      try {
413	        const advPost = await advancedPostGenerationHook({
414	          updatedState: testState,
415	          stateHistory: [],
416	        });
417	        if (advPost.enabled) {
418	          auditTrail.push(`[NEURO-POST] Singularity: ${advPost.singularity?.isSingularity ?? false}, PhaseShift: ${advPost.phaseTransition?.isPhaseShift ?? false}, Invariants: ${advPost.invariantReport?.violations?.length ?? 0}, Time: ${advPost.computeTimeMs.toFixed(2)}ms`);
419	        } else {
420	          auditTrail.push(`[NEURO-POST] Disabled (mode: ${advPost.mode})`);
421	        }
422	      } catch (err) {
423	        auditTrail.push(`[NEURO-POST] FAILED (non-blocking): ${err instanceof Error ? err.message : String(err)}`);
424	      }
425	
426	      const totalTimeMs = performance.now() - startTime;
427	      const metricsAfter = getGeometryMetrics();
428	      auditTrail.push(`[COMPLETE] Total diagnostic time: ${totalTimeMs.toFixed(2)}ms`);
429	
430	      return {
431	        success: true,
432	        totalTimeMs,
433	        preResult,
434	        postResult: postResult ?? null,
435	        metricsAfter,
436	        auditTrail,
437	        config: {
438	          geometryFlags: flags,
439	          runtimeMode: mode,
440	          neurocosmology: advancedDiag,
441	        },
442	      };
443	    }),
444	
445	  /**
446	   * Get fixation risk timeseries (for line charts).
447	   */
448	  getFixationTimeseries: adminProcedure
449	    .input(z.object({
450	      timeRangeHours: z.number().min(1).max(720).default(24),
451	      bucketMinutes: z.number().min(1).max(60).default(5),
452	    }).optional())
453	    .query(async ({ input }) => {
454	      const db = await getDb();
455	      const hours = input?.timeRangeHours ?? 24;
456	      const bucketMin = input?.bucketMinutes ?? 5;
457	      const since = new Date(Date.now() - hours * 60 * 60 * 1000);
458	
459	      const timeseries = await db
460	        .select({
461	          bucket: sql<string>`to_char(${geometrySnapshots.createdAt}, 'YYYY-MM-DD HH24:MI')`,
462	          avgFixation: avg(geometrySnapshots.fixationRisk),
463	          maxFixation: max(geometrySnapshots.fixationRisk),
464	          avgDrift: avg(geometrySnapshots.driftScore),
465	          count: count(),
466	        })
467	        .from(geometrySnapshots)
468	        .where(gte(geometrySnapshots.createdAt, since))
469	        .groupBy(sql`to_char(${geometrySnapshots.createdAt}, 'YYYY-MM-DD HH24:MI')`)
470	        .orderBy(sql`to_char(${geometrySnapshots.createdAt}, 'YYYY-MM-DD HH24:MI')`);
471	
472	      return { timeseries, timeRangeHours: hours, bucketMinutes: bucketMin };
473	    }),
474	
475	  /**
476	   * Get all feature flags for both geometry and neurocosmology runtimes.
477	   */
478	  getFeatureFlags: adminProcedure
479	    .query(async () => {
480	      const geometryFlags = getFlags();
481	      const geometryMode = getRuntimeMode();
482	      const neuroFlags = getAdvancedFlags();
483	      const neuroMode = getAdvancedRuntimeMode();
484	
485	      return {
486	        geometry: {
487	          flags: geometryFlags,
488	          mode: geometryMode,
489	          validModes: ['disabled', 'shadow', 'active', 'enforcing'] as GeometryRuntimeMode[],
490	        },
491	        neurocosmology: {
492	          flags: neuroFlags,
493	          mode: neuroMode,
494	          validModes: ['off', 'shadow', 'telemetry', 'advisory', 'active'] as AdvancedRuntimeMode[],
495	        },
496	      };
497	    }),
498	
499	  /**
500	   * Toggle a geometry feature flag at runtime.
501	   */
502	  setGeometryFlag: adminProcedure
503	    .input(z.object({
504	      flag: z.enum([
505	        'GEOMETRY_RUNTIME_ENABLED',
506	        'GEOMETRY_FORECAST_ENABLED',
507	        'GEOMETRY_FIXATION_ENABLED',
508	        'GEOMETRY_RESONANCE_ENABLED',
509	        'GEOMETRY_FIELD_LOGGING_ENABLED',
510	        'GEOMETRY_FORMAL_ENABLED',
511	      ]),
512	      value: z.boolean(),
513	    }))
514	    .mutation(async ({ input }) => {
515	      try {
516	        setGeometryFlag(input.flag as keyof GeometryFeatureFlags, input.value);
517	        return { success: true, flag: input.flag, value: input.value, updatedAt: Date.now() };
518	      } catch (error) {
519	        const message = error instanceof Error ? error.message : String(error);
520	        log.error({ flag: input.flag, error: message }, 'Failed to set geometry flag');
521	        throw new TRPCError({ code: 'INTERNAL_SERVER_ERROR', message: `Failed to set flag: ${message}` });
522	      }
523	    }),
524	
525	  /**
526	   * Set the geometry runtime mode.
527	   */
528	  setGeometryMode: adminProcedure
529	    .input(z.object({
530	      mode: z.enum(['disabled', 'shadow', 'active', 'enforcing']),
531	    }))
532	    .mutation(async ({ input }) => {
533	      try {
534	        setGeometryRuntimeMode(input.mode as GeometryRuntimeMode);
535	        return { success: true, mode: input.mode, updatedAt: Date.now() };
536	      } catch (error) {
537	        const message = error instanceof Error ? error.message : String(error);
538	        log.error({ mode: input.mode, error: message }, 'Failed to set geometry mode');
539	        throw new TRPCError({ code: 'BAD_REQUEST', message: `Failed to set mode: ${message}` });
540	      }
541	    }),
542	
543	  /**
544	   * Toggle a neurocosmology advanced feature flag at runtime.
545	   */
546	  setNeuroFlag: adminProcedure
547	    .input(z.object({
548	      flag: z.enum([
549	        'GEOMETRY_ADVANCED_ENABLED',
550	        'GEOMETRY_ADVANCED_ASYNC',
551	        'GEOMETRY_RESONANCE_ENABLED',
552	        'GEOMETRY_PHASE_TRANSITION_ALERTS',
553	        'GEOMETRY_MULTISCALE_ENABLED',
554	        'GEOMETRY_CONSERVATION_MONITOR',
555	      ]),
556	      value: z.boolean(),
557	    }))
558	    .mutation(async ({ input }) => {
559	      try {
