824	  // ─── Session Replay Procedures ──────────────────────────────────────
825	
826	  /**
827	   * Get detailed session information for replay viewer.
828	   */
829	  getSessionDetail: adminProcedure
830	    .input(z.object({
831	      sessionId: z.string(),
832	    }))
833	    .query(async ({ input }) => {
834	      const db = await getDb();
835	
836	      // Get session
837	      const [session] = await db
838	        .select()
839	        .from(geometrySessions)
840	        .where(eq(geometrySessions.sessionId, input.sessionId))
841	        .limit(1);
842	
843	      if (!session) {
844	        throw new TRPCError({ code: 'NOT_FOUND', message: `Session not found: ${input.sessionId}` });
845	      }
846	
847	      // Get all snapshots ordered by generation index
848	      const snapshots = await db
849	        .select()
850	        .from(geometrySnapshots)
851	        .where(eq(geometrySnapshots.sessionId, input.sessionId))
852	        .orderBy(geometrySnapshots.generationIndex);
853	
854	      // Get all events ordered by creation time
855	      const events = await db
856	        .select()
857	        .from(geometryEvents)
858	        .where(eq(geometryEvents.sessionId, input.sessionId))
859	        .orderBy(geometryEvents.createdAt);
860	
861	      // Compute snapshot diffs (compare consecutive snapshots)
862	      const snapshotDiffs = snapshots.map((snap, i) => {
863	        if (i === 0) return { index: snap.generationIndex, diffs: [] as string[] };
864	        const prev = snapshots[i - 1];
865	        const diffs: string[] = [];
866	
867	        if (snap.fixationRisk !== prev.fixationRisk) {
868	          const delta = snap.fixationRisk - prev.fixationRisk;
869	          diffs.push(`fixationRisk: ${prev.fixationRisk.toFixed(4)} → ${snap.fixationRisk.toFixed(4)} (${delta >= 0 ? '+' : ''}${delta.toFixed(4)})`);
870	        }
871	        if (snap.driftScore !== prev.driftScore) {
872	          const delta = snap.driftScore - prev.driftScore;
873	          diffs.push(`driftScore: ${prev.driftScore.toFixed(4)} → ${snap.driftScore.toFixed(4)} (${delta >= 0 ? '+' : ''}${delta.toFixed(4)})`);
874	        }
875	        if (snap.stabilityClass !== prev.stabilityClass) {
876	          diffs.push(`stabilityClass: ${prev.stabilityClass} → ${snap.stabilityClass}`);
877	        }
878	        if (snap.shouldConstrain !== prev.shouldConstrain) {
879	          diffs.push(`shouldConstrain: ${prev.shouldConstrain} → ${snap.shouldConstrain}`);
880	        }
881	        if (snap.loopDetected !== prev.loopDetected) {
882	          diffs.push(`loopDetected: ${prev.loopDetected} → ${snap.loopDetected}`);
883	        }
884	        if (snap.singularityDetected !== prev.singularityDetected) {
885	          diffs.push(`singularityDetected: ${prev.singularityDetected} → ${snap.singularityDetected}`);
886	        }
887	        if (snap.phaseTransitionDetected !== prev.phaseTransitionDetected) {
888	          diffs.push(`phaseTransitionDetected: ${prev.phaseTransitionDetected} → ${snap.phaseTransitionDetected}`);
889	        }
890	        if (snap.entropyDelta !== null && prev.entropyDelta !== null && snap.entropyDelta !== prev.entropyDelta) {
891	          diffs.push(`entropyDelta: ${prev.entropyDelta.toFixed(4)} → ${snap.entropyDelta.toFixed(4)}`);
892	        }
893	        if (snap.curvatureDelta !== null && prev.curvatureDelta !== null && snap.curvatureDelta !== prev.curvatureDelta) {
894	          diffs.push(`curvatureDelta: ${prev.curvatureDelta.toFixed(4)} → ${snap.curvatureDelta.toFixed(4)}`);
895	        }
896	
897	        return { index: snap.generationIndex, diffs };
898	      });
899	
900	      return {
901	        session,
902	        snapshots,
903	        events,
904	        snapshotDiffs,
905	        timeline: buildTimeline(snapshots, events),
906	      };
907	    }),
