1154	      incidentId: z.string(),
1155	      resolvedBy: z.string().default('admin'),
1156	      notes: z.string().optional(),
1157	    }))
1158	    .mutation(async ({ input }) => {
1159	      const success = await resolveIncident(input.incidentId, input.resolvedBy, input.notes);
1160	      return { success };
1161	    }),
1162	});
1163	
1164	// ─── Helper Functions ──────────────────────────────────────────────
1165	
1166	interface TimelineEntry {
1167	  timestamp: number;
1168	  type: 'snapshot' | 'event';
1169	  generationIndex: number | null;
1170	  label: string;
1171	  severity?: string;
1172	  data: Record<string, unknown>;
1173	}
1174	
1175	/**
1176	 * Build a unified timeline from snapshots and events for the replay viewer.
1177	 * Merges both data sources into a single chronological list.
1178	 */
1179	function buildTimeline(
1180	  snapshots: Array<{ createdAt: Date; generationIndex: number; fixationRisk: number; driftScore: number; stabilityClass: string; shouldConstrain: boolean; loopDetected: boolean | null; singularityDetected: boolean | null; phaseTransitionDetected: boolean | null; entropyDelta: number | null; curvatureDelta: number | null; preComputeTimeMs: number; postComputeTimeMs: number | null }>,
1181	  events: Array<{ createdAt: Date; eventType: string; severity: string; message: string | null; generationIndex: number | null; metadata: Record<string, unknown> | null }>,
1182	): TimelineEntry[] {
1183	  const timeline: TimelineEntry[] = [];
1184	
1185	  // Add snapshots
1186	  for (const snap of snapshots) {
1187	    timeline.push({
1188	      timestamp: new Date(snap.createdAt).getTime(),
1189	      type: 'snapshot',
1190	      generationIndex: snap.generationIndex,
1191	      label: `Gen #${snap.generationIndex}: fixation=${(snap.fixationRisk * 100).toFixed(1)}%, drift=${(snap.driftScore * 100).toFixed(1)}%, stability=${snap.stabilityClass}`,
1192	      data: {
1193	        fixationRisk: snap.fixationRisk,
1194	        driftScore: snap.driftScore,
1195	        stabilityClass: snap.stabilityClass,
1196	        shouldConstrain: snap.shouldConstrain,
1197	        loopDetected: snap.loopDetected,
1198	        singularityDetected: snap.singularityDetected,
1199	        phaseTransitionDetected: snap.phaseTransitionDetected,
1200	        entropyDelta: snap.entropyDelta,
1201	        curvatureDelta: snap.curvatureDelta,
1202	        computeTimeMs: snap.preComputeTimeMs + (snap.postComputeTimeMs ?? 0),
1203	      },
1204	    });
1205	  }
1206	
1207	  // Add events
1208	  for (const event of events) {
1209	    timeline.push({
1210	      timestamp: new Date(event.createdAt).getTime(),
1211	      type: 'event',
1212	      generationIndex: event.generationIndex,
1213	      label: event.message ?? event.eventType,
1214	      severity: event.severity,
1215	      data: {
1216	        eventType: event.eventType,
1217	        severity: event.severity,
1218	        metadata: event.metadata,
1219	      },
1220	    });
1221	  }
1222	
1223	  // Sort chronologically
1224	  timeline.sort((a, b) => a.timestamp - b.timestamp);
1225	
1226	  return timeline;
1227	}
