/**
 * Create a domain-specific child logger.
 * Usage:
 *   const log = createLogger('webhook');
 *   log.info({ eventId: 'evt_123' }, 'Processing webhook event');
 *   log.error({ err }, 'Webhook processing failed');
 *   log.info('Simple message');
 *   log.warn('Message with data', { key: 'value' });
 */
export function createLogger(domain: LogDomain, context?: Record<string, unknown>): GravitoLogger {
  return baseLogger.child({
    domain,
    ...context,
  });
}

/**
 * Create a request-scoped logger with correlation ID.
 * Usage in Express middleware:
 *   const log = createRequestLogger('api', req);
 *   log.info('Processing request');
 */
export function createRequestLogger(domain: LogDomain, req?: { headers?: Record<string, string | string[] | undefined> }): GravitoLogger {
  const correlationId = (req?.headers?.['x-correlation-id'] as string) || generateCorrelationId();
  return baseLogger.child({
    domain,
    correlationId,
  });
}

/**
 * Safe log helper that redacts PII from data before logging.
 * Use for any data that might contain user information.
 */
export function safeLog(logger: GravitoLogger, level: 'info' | 'warn' | 'error' | 'debug', data: Record<string, unknown>, message: string) {
  const redacted = redactPII(data) as Record<string, unknown>;
  logger[level](redacted, message);
}

// ============================================================================
// EXPRESS MIDDLEWARE
// ============================================================================
/**
 * Express middleware that adds a correlation ID to every request
 * and logs request/response pairs.
 */
export function requestLoggingMiddleware() {
  const httpLogger = createLogger('api');

  return (req: any, res: any, next: any) => {
    const correlationId = (req.headers['x-correlation-id'] as string) || generateCorrelationId();
    req.correlationId = correlationId;
    res.setHeader('x-correlation-id', correlationId);

    const startTime = Date.now();

    // Log on response finish
    res.on('finish', () => {
      const duration = Date.now() - startTime;
      const logData = {
        correlationId,
        method: req.method,
        url: req.originalUrl || req.url,
        statusCode: res.statusCode,
        duration,
        userAgent: req.headers['user-agent'],
      };

      if (res.statusCode >= 500) {
        httpLogger.error(logData, 'Request failed');
      } else if (res.statusCode >= 400) {
        httpLogger.warn(logData, 'Request client error');
      } else if (duration > 5000) {
        httpLogger.warn(logData, 'Slow request');
      } else {
        // Only log non-health-check requests at info level
        if (!req.url?.includes('/health') && !req.url?.includes('/favicon')) {
          httpLogger.debug(logData, 'Request completed');
        }
      }
    });

    next();
  };
}

