tool_use_result.originalFile:
/**
 * Geometry Admin Router — tRPC endpoints for the /admin/geometry dashboard.
 * 
 * Provides real-time and historical data for emotional geometry monitoring:
 * - Session listing with aggregate metrics
 * - Snapshot timeseries for longitudinal analysis
 * - Event timeline for alerts and interventions
 * - Live state from the runtime bridge
 * - Prometheus-style metrics export
 */

import { z } from 'zod';
import { TRPCError } from '@trpc/server';
import { createLogger } from '../_core/logger';

const log = createLogger('geometry-admin-router');
import { adminProcedure, router } from '../_core/trpc';
import { getDb } from '../db';
import { geometrySessions, geometrySnapshots, geometryEvents } from '../../drizzle/schema';
import { desc, eq, and, gte, count, avg, max, sql } from 'drizzle-orm';
import { createSafeDefaults, preGenerationHook, postGenerationHook } from '../emotional-geometry-runtime/geometry-runtime-bridge';
import { getGeometryMetrics, resetGeometryMetrics, recordPreHook, recordPostHook } from '../emotional-geometry-runtime/geometry-metrics';
import { getFlags, getRuntimeMode, setGeometryFlag, setGeometryRuntimeMode, type GeometryFeatureFlags, type GeometryRuntimeMode } from '../emotional-geometry-runtime/feature-flags';
import { advancedPreGenerationHook, advancedPostGenerationHook } from '../neurocosmology-runtime-advanced/integration-hooks';
import { getAdvancedFlagDiagnostics, getAdvancedFlags, getAdvancedRuntimeMode, setAdvancedFlag, setAdvancedRuntimeMode, type AdvancedFeatureFlags, type AdvancedRuntimeMode } from '../neurocosmology-runtime-advanced/feature-flags';
import { getAlertConfigs, getAlertConfig, setAlertThreshold, setAlertEnabled, setAlertCooldown, setAlertSeverity, resetAlertConfigs, getAlertHistory, getAlertHistoryFromDb, acknowledgeAlert, acknowledgeAlertPersistent, getAlertSummary, getUnacknowledgedCount, getNotificationChannels, createNotificationChannel, updateNotificationChannel, deleteNotificationChannel, evaluateAlerts, ALERT_TYPES, type AlertType, type AlertSeverity } from '../emotional-geometry-runtime/geometry-alerting';
import { getEscalationPolicies, createEscalationPolicy, updateEscalationPolicy, deleteEscalationPolicy, getEscalationHistory, runEscalationCheck, isEscalationEngineRunning, getSSEClientCount, type EscalationPolicyConfig } from '../emotional-geometry-runtime/escalation-engine';
import { getAlertFrequencyByType, getAlertSummaryStats, getIncidents, getIncidentDetail, resolveIncident, acknowledgeIncident } from '../emotional-geometry-runtime/alert-analytics';

export const geometryAdminRouter = router({
  // =========================================================================
  // NEUROCOSMOLOGY VALIDATION ENDPOINTS
  // =========================================================================

  /**
   * Get neurocosmology validation status — calibration state, recent runs,
   * proof bundles, registered backends.
   * Exposed at /admin/neurocosmology in the dashboard.
   */
  neurocosmologyStatus: adminProcedure
    .query(async () => {
      const { getNeurocosmologyStatus } = await import(
        '../emotional-geometry-runtime/validation/validationOrchestrator'
      );
      return getNeurocosmologyStatus();
    }),

  /**
   * Trigger a validation run (on-demand, not just nightly).
   * Requires at least 2 model backends configured via env vars.
   */
  triggerValidation: adminProcedure
    .input(z.object({
      modelIds: z.array(z.string()).optional(),
      stimuliSubset: z.array(z.string()).optional(),
      skipHumanCalibration: z.boolean().optional(),
    }).optional())
    .mutation(async ({ input }) => {
      const { runValidation } = await import(
        '../emotional-geometry-runtime/validation/validationOrchestrator'
      );
      return runValidation(input ?? undefined);
    }),

  /**
   * Get current calibration state (hot-path, in-memory).
   */
  calibrationState: adminProcedure
    .query(async () => {
      const { getCalibrationState } = await import(
        '../emotional-geometry-runtime/validation/calibrationMode'
      );
      return getCalibrationState();
    }),

  /**
   * Check whether field-driven boosts are currently active.
   */
  fieldBoostsActive: adminProcedure
    .query(async () => {
      const { areFieldBoostsActive } = await import(
        '../emotional-geometry-runtime/validation/calibrationMode'
      );
      return { active: areFieldBoostsActive() };
    }),

  /**
   * Get recent proof bundles for provenance audit.
   */
  proofBundles: adminProcedure
    .input(z.object({ limit: z.number().min(1).max(100).default(10) }).optional())
    .query(async ({ input }) => {
      const { getRecentProofBundles } = await import(
        '../emotional-geometry-runtime/validation/calibrationMode'
      );
      return getRecentProofBundles(input?.limit ?? 10);
    }),

  // =========================================================================
  // ORIGINAL GEOMETRY ADMIN ENDPOINTS
  // =========================================================================

  /**
   * Get overview stats for the geometry dashboard header cards.
   */
  getOverview: adminProcedure
    .input(z.object({
      timeRangeHours: z.number().min(1).max(720).default(24),
    }).optional())
    .query(async ({ input }) => {
      const db = await getDb();
      if (!db) throw new TRPCError({ code: 'INTERNAL_SERVER_ERROR', message: 'Database not available' });
      const hours = input?.timeRangeHours ?? 24;
      const since = new Date(Date.now() - hours * 60 * 60 * 1000);

      const [sessionStats] = await db
        .select({
          totalSessions: count(),
          avgFixation: avg(geometrySessions.avgFixationRisk),
          avgDrift: avg(geometrySessions.avgDriftScore),
          maxFixation: max(geometrySessions.maxFixationRisk),
          maxDrift: max(geometrySessions.maxDriftScore),
          avgCompute: avg(geometrySessions.avgComputeTimeMs),
        })
        .from(geometrySessions)
        .where(gte(geometrySessions.createdAt, since));

      const [snapshotStats] = await db
        .select({
          totalGenerations: count(),
          constraintsInjected: sql<number>`SUM(CASE WHEN ${geometrySnapshots.shouldConstrain} = true THEN 1 ELSE 0 END)`,
          loopsDetected: sql<number>`SUM(CASE WHEN ${geometrySnapshots.loopDetected} = true THEN 1 ELSE 0 END)`,
          singularities: sql<number>`SUM(CASE WHEN ${geometrySnapshots.singularityDetected} = true THEN 1 ELSE 0 END)`,
          phaseTransitions: sql<number>`SUM(CASE WHEN ${geometrySnapshots.phaseTransitionDetected} = true THEN 1 ELSE 0 END)`,
        })
        .from(geometrySnapshots)
        .where(gte(geometrySnapshots.createdAt, since));

      const [eventStats] = await db
        .select({
          totalEvents: count(),
          criticalEvents: sql<number>`SUM(CASE WHEN ${geometryEvents.severity} = 'critical' THEN 1 ELSE 0 END)`,
          warningEvents: sql<number>`SUM(CASE WHEN ${geometryEvents.severity} = 'warning' THEN 1 ELSE 0 END)`,
        })
        .from(geometryEvents)
        .where(gte(geometryEvents.createdAt, since));

      return {
        timeRangeHours: hours,
        sessions: {
          total: sessionStats?.totalSessions ?? 0,
          avgFixationRisk: Number(sessionStats?.avgFixation ?? 0),
          avgDriftScore: Number(sessionStats?.avgDrift ?? 0),
          maxFixationRisk: Number(sessionStats?.maxFixation ?? 0),
          maxDriftScore: Number(sessionStats?.maxDrift ?? 0),
          avgComputeTimeMs: Number(sessionStats?.avgCompute ?? 0),
        },
        generations: {
          total: snapshotStats?.totalGenerations ?? 0,
          constraintsInjected: Number(snapshotStats?.constraintsInjected ?? 0),
          loopsDetected: Number(snapshotStats?.loopsDetected ?? 0),
          singularities: Number(snapshotStats?.singularities ?? 0),
          phaseTransitions: Number(snapshotStats?.phaseTransitions ?? 0),
        },
        events: {
          total: eventStats?.totalEvents ?? 0,
          critical: Number(eventStats?.criticalEvents ?? 0),
          warnings: Number(eventStats?.warningEvents ?? 0),
        },
        metrics: getGeometryMetrics(),
      };
    }),

  /**
   * List geometry sessions with pagination.
   */
  listSessions: adminProcedure
    .input(z.object({
      limit: z.number().min(1).max(100).default(20),
      offset: z.number().min(0).default(0),
      status: z.enum(["active", "completed", "error"]).optional(),
    }).optional())
    .query(async ({ input }) => {
      const db = await getDb();
      if (!db) throw new TRPCError({ code: 'INTERNAL_SERVER_ERROR', message: 'Database not available' });
      const limit = input?.limit ?? 20;
      const offset = input?.offset ?? 0;
      const status = input?.status;

      const conditions = status ? [eq(geometrySessions.status, status)] : [];

      const sessions = await db
        .select()
        .from(geometrySessions)
        .where(conditions.length > 0 ? and(...conditions) : undefined)
        .orderBy(desc(geometrySessions.createdAt))
        .limit(limit)
        .offset(offset);

      const [{ total }] = await db
        .select({ total: count() })
        .from(geometrySessions)
        .where(conditions.length > 0 ? and(...conditions) : undefined);

      return { sessions, total, limit, offset };
    }),

  /**
   * Get snapshots for a specific session (timeseries data).
   */
  getSessionSnapshots: adminProcedure
    .input(z.object({
      sessionId: z.string(),
      limit: z.number().min(1).max(500).default(100),
    }))
    .query(async ({ input }) => {
      const db = await getDb();
      if (!db) throw new TRPCError({ code: 'INTERNAL_SERVER_ERROR', message: 'Database not available' });
      const snapshots = await db
        .select()
        .from(geometrySnapshots)
        .where(eq(geometrySnapshots.sessionId, input.sessionId))
        .orderBy(geometrySnapshots.generationIndex)
        .limit(input.limit);

      return { snapshots, sessionId: input.sessionId };
    }),

  /**
   * Get event timeline with filtering.
   */
  getEvents: adminProcedure
    .input(z.object({
      limit: z.number().min(1).max(200).default(50),
      offset: z.number().min(0).default(0),
      eventType: z.string().optional(),
      severity: z.enum(["info", "warning", "critical"]).optional(),
      sessionId: z.string().optional(),
      timeRangeHours: z.number().min(1).max(720).default(24),
    }).optional())
    .query(async ({ input }) => {
      const db = await getDb();
      if (!db) throw new TRPCError({ code: 'INTERNAL_SERVER_ERROR', message: 'Database not available' });
      const limit = input?.limit ?? 50;
      const offset = input?.offset ?? 0;
      const since = new Date(Date.now() - (input?.timeRangeHours ?? 24) * 60 * 60 * 1000);

      const conditions = [gte(geometryEvents.createdAt, since)];
      if (input?.severity) conditions.push(eq(geometryEvents.severity, input.severity));
      if (input?.sessionId) conditions.push(eq(geometryEvents.sessionId, input.sessionId));

      const events = await db
        .select()
        .from(geometryEvents)
        .where(and(...conditions))
        .orderBy(desc(geometryEvents.createdAt))
        .limit(limit)
        .offset(offset);

      const [{ total }] = await db
        .select({ total: count() })
        .from(geometryEvents)
        .where(and(...conditions));

      return { events, total, limit, offset };
    }),

  /**
   * Get the current runtime state (live, not from DB).
   */
  getLiveState: adminProcedure
    .query(async () => {
      const safeDefaults = createSafeDefaults();
      const metrics = getGeometryMetrics();

      return {
        runtimeStatus: 'active',
        safeDefaults,
        metrics,
        timestamp: Date.now(),
      };
    }),

  /**
   * Get Prometheus-style metrics export.
   */
  getMetrics: adminProcedure
    .query(async () => {
      return getGeometryMetrics();
    }),

  /**
   * Reset metrics counters (admin action).
   */
  resetMetrics: adminProcedure
    .mutation(async () => {
      resetGeometryMetrics();
      return { success: true, resetAt: Date.now() };
    }),

  /**
   * Get stability distribution over time (for charts).
   */
  getStabilityDistribution: adminProcedure
    .input(z.object({
      timeRangeHours: z.number().min(1).max(720).default(24),
    }).optional())
    .query(async ({ input }) => {
      const db = await getDb();
      if (!db) throw new TRPCError({ code: 'INTERNAL_SERVER_ERROR', message: 'Database not available' });
      const since = new Date(Date.now() - (input?.timeRangeHours ?? 24) * 60 * 60 * 1000);

      const distribution = await db
        .select({
          stabilityClass: geometrySnapshots.stabilityClass,
          count: count(),
        })
        .from(geometrySnapshots)
        .where(gte(geometrySnapshots.createdAt, since))
        .groupBy(geometrySnapshots.stabilityClass);

      return { distribution, timeRangeHours: input?.timeRangeHours ?? 24 };
    }),

  /**
   * Diagnostic: trigger a live governed generation through the full geometry pipeline.
   * Returns the complete audit trail showing pre-hook → post-hook → metrics recording.
   */
  diagnosticGeneration: adminProcedure
    .input(z.object({
      prompt: z.string().min(1).max(500).default('What is emotional intelligence and why does it matter?'),
      currentState: z.record(z.string(), z.number()).optional(),
    }).optional())
    .mutation(async ({ input, ctx }) => {
      const startTime = performance.now();
      const auditTrail: string[] = [];
      const flags = getFlags();
      const mode = getRuntimeMode();
      const advancedDiag = getAdvancedFlagDiagnostics();

      auditTrail.push(`[CONFIG] Runtime: ${flags.GEOMETRY_RUNTIME_ENABLED ? 'ENABLED' : 'DISABLED'}, Mode: ${mode}`);
      auditTrail.push(`[CONFIG] Flags: ${JSON.stringify(flags)}`);
      auditTrail.push(`[CONFIG] Neuro advanced: ${advancedDiag.enabled ? 'ENABLED' : 'DISABLED'}, Mode: ${advancedDiag.mode}`);

      const testState = input?.currentState ?? {
        emotionalMass: 5.0,
        emotionalCharge: 0.3,
        emotionalDistance: 2.0,
        attentionCurvature: 1.5,
        memoryEntropy: 0.7,
        emotionalEnergy: 12.5,
        subconscious_density: 0.4,
        recurrenceCount: 3,
        topicDiversity: 0.6,
        emotionalValence: 0.2,
        arousalLevel: 0.5,
        coherenceScore: 0.8,
      };

      // Step 1: Pre-generation hook
      let preResult;
      try {
        preResult = await preGenerationHook({
          sessionId: `diag_${Date.now()}`,
          userId: `admin-${ctx.user.id}`,
          prompt: input?.prompt ?? 'What is emotional intelligence and why does it matter?',
          currentState: testState,
        });
        auditTrail.push(`[PRE-HOOK] Hash: ${preResult.preStateHash}, Fixation: ${preResult.fixationRisk.toFixed(4)}, Drift: ${preResult.driftScore.toFixed(4)}, Stability: ${preResult.stabilityClass}, Eigen: ${preResult.eigenClassification}, Constrain: ${preResult.shouldConstrain}, Time: ${preResult.computeTimeMs.toFixed(2)}ms`);
        if (preResult.constraintsInjected.length > 0) {
          auditTrail.push(`[PRE-HOOK] Constraints: ${preResult.constraintsInjected.join(', ')}`);
        }
        // Record metrics
        recordPreHook(preResult.fixationRisk, preResult.driftScore, preResult.computeTimeMs);
        auditTrail.push(`[METRICS] Pre-hook metrics recorded`);
      } catch (err) {
        auditTrail.push(`[PRE-HOOK] FAILED: ${err instanceof Error ? err.message : String(err)}`);
        preResult = createSafeDefaults();
      }

      // Step 2: Advanced neurocosmology pre-hook
      try {
        const advPre = await advancedPreGenerationHook({
          currentState: testState,
          stateHistory: [],
        });
        if (advPre.enabled) {
          auditTrail.push(`[NEURO-PRE] Mode: ${advPre.mode}, Singularity: ${advPre.singularity?.isSingularity ?? false}, PhaseShift: ${advPre.phaseTransition?.isPhaseShift ?? false}, Invariants: ${advPre.invariantReport?.violations?.length ?? 0}, Time: ${advPre.computeTimeMs.toFixed(2)}ms`);
        } else {
          auditTrail.push(`[NEURO-PRE] Disabled (mode: ${advPre.mode})`);
        }
      } catch (err) {
        auditTrail.push(`[NEURO-PRE] FAILED (non-blocking): ${err instanceof Error ? err.message : String(err)}`);
      }

      // Step 3: Simulate LLM output (we don't actually call LLM in diagnostic mode)
      const simulatedOutput = 'Emotional intelligence is the ability to recognize, understand, and manage our own emotions while also being able to recognize, understand, and influence the emotions of others. It matters because it affects our relationships, decision-making, and overall well-being.';
      auditTrail.push(`[LLM] Simulated output (${simulatedOutput.length} chars) — diagnostic mode does not call real LLM`);

      // Step 4: Post-generation hook
      let postResult;
      try {
        postResult = await postGenerationHook({
          sessionId: `diag_${Date.now()}`,
          output: simulatedOutput,
          preResult,
        });
        auditTrail.push(`[POST-HOOK] Hash: ${postResult.postStateHash}, EntropyΔ: ${postResult.entropyDelta.toFixed(4)}, CurvatureΔ: ${postResult.curvatureDelta.toFixed(4)}, Loop: ${postResult.loopDetected}, Time: ${postResult.computeTimeMs.toFixed(2)}ms`);
        // Record metrics
        recordPostHook(postResult.loopDetected, postResult.computeTimeMs);
        auditTrail.push(`[METRICS] Post-hook metrics recorded`);
      } catch (err) {
        auditTrail.push(`[POST-HOOK] FAILED: ${err instanceof Error ? err.message : String(err)}`);
      }

      // Step 5: Advanced neurocosmology post-hook
      try {
        const advPost = await advancedPostGenerationHook({
          updatedState: testState,
          stateHistory: [],
        });
        if (advPost.enabled) {
          auditTrail.push(`[NEURO-POST] Singularity: ${advPost.singularity?.isSingularity ?? false}, PhaseShift: ${advPost.phaseTransition?.isPhaseShift ?? false}, Invariants: ${advPost.invariantReport?.violations?.length ?? 0}, Time: ${advPost.computeTimeMs.toFixed(2)}ms`);
        } else {
          auditTrail.push(`[NEURO-POST] Disabled (mode: ${advPost.mode})`);
        }
      } catch (err) {
        auditTrail.push(`[NEURO-POST] FAILED (non-blocking): ${err instanceof Error ? err.message : String(err)}`);
      }

      const totalTimeMs = performance.now() - startTime;
      const metricsAfter = getGeometryMetrics();
      auditTrail.push(`[COMPLETE] Total diagnostic time: ${totalTimeMs.toFixed(2)}ms`);

      return {
        success: true,
        totalTimeMs,
        preResult,
        postResult: postResult ?? null,
        metricsAfter,
        auditTrail,
        config: {
          geometryFlags: flags,
          runtimeMode: mode,
          neurocosmology: advancedDiag,
        },
      };
    }),

  /**
   * Get fixation risk timeseries (for line charts).
   */
  getFixationTimeseries: adminProcedure
    .input(z.object({
      timeRangeHours: z.number().min(1).max(720).default(24),
      bucketMinutes: z.number().min(1).max(60).default(5),
    }).optional())
    .query(async ({ input }) => {
      const db = await getDb();
      if (!db) throw new TRPCError({ code: 'INTERNAL_SERVER_ERROR', message: 'Database not available' });
      const hours = input?.timeRangeHours ?? 24;
      const bucketMin = input?.bucketMinutes ?? 5;
      const since = new Date(Date.now() - hours * 60 * 60 * 1000);

      const timeseries = await db
        .select({
          bucket: sql<string>`to_char(${geometrySnapshots.createdAt}, 'YYYY-MM-DD HH24:MI')`,
          avgFixation: avg(geometrySnapshots.fixationRisk),
          maxFixation: max(geometrySnapshots.fixationRisk),
          avgDrift: avg(geometrySnapshots.driftScore),
          count: count(),
        })
        .from(geometrySnapshots)
        .where(gte(geometrySnapshots.createdAt, since))
        .groupBy(sql`to_char(${geometrySnapshots.createdAt}, 'YYYY-MM-DD HH24:MI')`)
        .orderBy(sql`to_char(${geometrySnapshots.createdAt}, 'YYYY-MM-DD HH24:MI')`);

      return { timeseries, timeRangeHours: hours, bucketMinutes: bucketMin };
    }),

  /**
   * Get all feature flags for both geometry and neurocosmology runtimes.
   */
  getFeatureFlags: adminProcedure
    .query(async () => {
      const geometryFlags = getFlags();
      const geometryMode = getRuntimeMode();
      const neuroFlags = getAdvancedFlags();
      const neuroMode = getAdvancedRuntimeMode();

      return {
        geometry: {
          flags: geometryFlags,
          mode: geometryMode,
          validModes: ['disabled', 'shadow', 'active', 'enforcing'] as GeometryRuntimeMode[],
        },
        neurocosmology: {
          flags: neuroFlags,
          mode: neuroMode,
          validModes: ['off', 'shadow', 'telemetry', 'advisory', 'active'] as AdvancedRuntimeMode[],
        },
      };
    }),

  /**
   * Toggle a geometry feature flag at runtime.
   */
  setGeometryFlag: adminProcedure
    .input(z.object({
      flag: z.enum([
        'GEOMETRY_RUNTIME_ENABLED',
        'GEOMETRY_FORECAST_ENABLED',
        'GEOMETRY_FIXATION_ENABLED',
        'GEOMETRY_RESONANCE_ENABLED',
        'GEOMETRY_FIELD_LOGGING_ENABLED',
        'GEOMETRY_FORMAL_ENABLED',
      ]),
      value: z.boolean(),
    }))
    .mutation(async ({ input }) => {
      try {
        setGeometryFlag(input.flag as keyof GeometryFeatureFlags, input.value);
        return { success: true, flag: input.flag, value: input.value, updatedAt: Date.now() };
      } catch (error) {
        const message = error instanceof Error ? error.message : String(error);
        log.error({ flag: input.flag, error: message }, 'Failed to set geometry flag');
        throw new TRPCError({ code: 'INTERNAL_SERVER_ERROR', message: `Failed to set flag: ${message}` });
      }
    }),

  /**
   * Set the geometry runtime mode.
   */
  setGeometryMode: adminProcedure
    .input(z.object({
      mode: z.enum(['disabled', 'shadow', 'active', 'enforcing']),
    }))
    .mutation(async ({ input }) => {
      try {
        setGeometryRuntimeMode(input.mode as GeometryRuntimeMode);
        return { success: true, mode: input.mode, updatedAt: Date.now() };
      } catch (error) {
        const message = error instanceof Error ? error.message : String(error);
        log.error({ mode: input.mode, error: message }, 'Failed to set geometry mode');
        throw new TRPCError({ code: 'BAD_REQUEST', message: `Failed to set mode: ${message}` });
      }
    }),

  /**
   * Toggle a neurocosmology advanced feature flag at runtime.
   */
  setNeuroFlag: adminProcedure
    .input(z.object({
      flag: z.enum([
        'GEOMETRY_ADVANCED_ENABLED',
        'GEOMETRY_ADVANCED_ASYNC',
        'GEOMETRY_RESONANCE_ENABLED',
        'GEOMETRY_PHASE_TRANSITION_ALERTS',
        'GEOMETRY_MULTISCALE_ENABLED',
        'GEOMETRY_CONSERVATION_MONITOR',
      ]),
      value: z.boolean(),
    }))
    .mutation(async ({ input }) => {
      try {
        setAdvancedFlag(input.flag as keyof AdvancedFeatureFlags, input.value);
        return { success: true, flag: input.flag, value: input.value, updatedAt: Date.now() };
      } catch (error) {
        const message = error instanceof Error ? error.message : String(error);
        log.error({ flag: input.flag, error: message }, 'Failed to set neuro flag');
        throw new TRPCError({ code: 'INTERNAL_SERVER_ERROR', message: `Failed to set flag: ${message}` });
      }
    }),

  // ─── Alerting Procedures ────────────────────────────────────────────

  /**
   * Get all alert configurations and summary statistics.
   */
  getAlertConfig: adminProcedure
    .query(async () => {
      return {
        configs: await getAlertConfigs(),
        summary: getAlertSummary(),
        alertTypes: ALERT_TYPES,
      };
    }),

  /**
   * Update alert threshold for a specific alert type.
   */
  setAlertThreshold: adminProcedure
    .input(z.object({
      alertType: z.enum([
        'high_fixation_risk',
        'high_drift_score',
        'high_loop_rate',
        'singularity_burst',
        'phase_transition_burst',
        'invariant_violation_accumulation',
        'compute_degradation',
      ]),
      threshold: z.number().min(0),
    }))
    .mutation(async ({ input, ctx }) => {
      try {
        await setAlertThreshold(input.alertType as AlertType, input.threshold, `admin-${ctx.user.id}`);
        return { success: true, alertType: input.alertType, threshold: input.threshold, updatedAt: Date.now() };
      } catch (error) {
        const message = error instanceof Error ? error.message : String(error);
        log.error({ alertType: input.alertType, error: message }, 'Failed to set alert threshold');
        throw new TRPCError({ code: 'BAD_REQUEST', message: `Failed to set threshold: ${message}` });
      }
    }),

  /**
   * Enable or disable a specific alert type.
   */
  setAlertEnabled: adminProcedure
    .input(z.object({
      alertType: z.enum([
        'high_fixation_risk',
        'high_drift_score',
        'high_loop_rate',
        'singularity_burst',
        'phase_transition_burst',
        'invariant_violation_accumulation',
        'compute_degradation',
      ]),
      enabled: z.boolean(),
    }))
    .mutation(async ({ input, ctx }) => {
      try {
        await setAlertEnabled(input.alertType as AlertType, input.enabled, `admin-${ctx.user.id}`);
        return { success: true, alertType: input.alertType, enabled: input.enabled, updatedAt: Date.now() };
      } catch (error) {
        const message = error instanceof Error ? error.message : String(error);
        log.error({ alertType: input.alertType, error: message }, 'Failed to set alert enabled');
        throw new TRPCError({ code: 'BAD_REQUEST', message: `Failed to set enabled: ${message}` });
      }
    }),

  /**
   * Update cooldown period for a specific alert type.
   */
  setAlertCooldown: adminProcedure
    .input(z.object({
      alertType: z.enum([
        'high_fixation_risk',
        'high_drift_score',
        'high_loop_rate',
        'singularity_burst',
        'phase_transition_burst',
        'invariant_violation_accumulation',
        'compute_degradation',
      ]),
      cooldownMs: z.number().min(30000),
    }))
    .mutation(async ({ input, ctx }) => {
      try {
        await setAlertCooldown(input.alertType as AlertType, input.cooldownMs, `admin-${ctx.user.id}`);
        return { success: true, alertType: input.alertType, cooldownMs: input.cooldownMs, updatedAt: Date.now() };
      } catch (error) {
        const message = error instanceof Error ? error.message : String(error);
        log.error({ alertType: input.alertType, error: message }, 'Failed to set alert cooldown');
        throw new TRPCError({ code: 'BAD_REQUEST', message: `Failed to set cooldown: ${message}` });
      }
    }),

  /**
   * Update severity for a specific alert type.
   */
  setAlertSeverity: adminProcedure
    .input(z.object({
      alertType: z.enum([
        'high_fixation_risk',
        'high_drift_score',
        'high_loop_rate',
        'singularity_burst',
        'phase_transition_burst',
        'invariant_violation_accumulation',
        'compute_degradation',
      ]),
      severity: z.enum(['warning', 'critical']),
    }))
    .mutation(async ({ input, ctx }) => {
      try {
        await setAlertSeverity(input.alertType as AlertType, input.severity as AlertSeverity, `admin-${ctx.user.id}`);
        return { success: true, alertType: input.alertType, severity: input.severity, updatedAt: Date.now() };
      } catch (error) {
        const message = error instanceof Error ? error.message : String(error);
        log.error({ alertType: input.alertType, error: message }, 'Failed to set alert severity');
        throw new TRPCError({ code: 'BAD_REQUEST', message: `Failed to set severity: ${message}` });
      }
    }),

  /**
   * Reset all alert configurations to defaults.
   */
  resetAlertConfigs: adminProcedure
    .mutation(async ({ ctx }) => {
      await resetAlertConfigs(`admin-${ctx.user.id}`);
      return { success: true, resetAt: Date.now() };
    }),

  /**
   * Get alert history with optional filtering.
   */
  getAlertHistory: adminProcedure
    .input(z.object({
      alertType: z.enum([
        'high_fixation_risk',
        'high_drift_score',
        'high_loop_rate',
        'singularity_burst',
        'phase_transition_burst',
        'invariant_violation_accumulation',
        'compute_degradation',
      ]).optional(),
      severity: z.enum(['warning', 'critical']).optional(),
      acknowledged: z.boolean().optional(),
      limit: z.number().min(1).max(200).default(50),
    }).optional())
    .query(async ({ input }) => {
      const history = await getAlertHistoryFromDb({
        alertType: input?.alertType as AlertType | undefined,
        severity: input?.severity as AlertSeverity | undefined,
        acknowledged: input?.acknowledged,
        limit: input?.limit ?? 50,
      });
      const summary = getAlertSummary();
      return { history, summary };
    }),

  /**
   * Acknowledge an alert by ID.
   */
  acknowledgeAlert: adminProcedure
    .input(z.object({
      alertId: z.string(),
    }))
    .mutation(async ({ input, ctx }) => {
      const success = await acknowledgeAlertPersistent(input.alertId, `admin-${ctx.user.id}`);
      if (!success) {
        throw new TRPCError({ code: 'NOT_FOUND', message: `Alert not found: ${input.alertId}` });
      }
      return { success: true, alertId: input.alertId, acknowledgedAt: Date.now() };
    }),

  /**
   * Get count of unacknowledged alerts (lightweight polling for sidebar badge).
   */
  getUnacknowledgedCount: adminProcedure
    .query(async () => {
      const count = await getUnacknowledgedCount();
      return { count };
    }),

  // ─── Notification Channel Management ──────────────────────────────

  /**
   * List all notification channels.
   */
  getNotificationChannels: adminProcedure
    .query(async () => {
      return await getNotificationChannels();
    }),

  /**
   * Create a new notification channel.
   */
  createNotificationChannel: adminProcedure
    .input(z.object({
      name: z.string().min(1).max(128),
      channelType: z.enum(['owner', 'slack', 'email']),
      enabled: z.boolean().default(true),
      config: z.object({
        webhookUrl: z.string().url().optional(),
        emailTo: z.string().email().optional(),
        emailFrom: z.string().email().optional(),
      }).optional(),
      alertTypes: z.array(z.string()).optional(),
      minSeverity: z.enum(['warning', 'critical']).default('warning'),
    }))
    .mutation(async ({ input }) => {
      const id = await createNotificationChannel(input);
      return { success: true, id, createdAt: Date.now() };
    }),

  /**
   * Update an existing notification channel.
   */
  updateNotificationChannel: adminProcedure
    .input(z.object({
      id: z.number(),
      name: z.string().min(1).max(128).optional(),
      enabled: z.boolean().optional(),
      config: z.object({
        webhookUrl: z.string().url().optional(),
        emailTo: z.string().email().optional(),
        emailFrom: z.string().email().optional(),
      }).optional(),
      alertTypes: z.array(z.string()).optional(),
      minSeverity: z.enum(['warning', 'critical']).optional(),
    }))
    .mutation(async ({ input }) => {
      const { id, ...updates } = input;
      const success = await updateNotificationChannel(id, updates);
      if (!success) {
        throw new TRPCError({ code: 'INTERNAL_SERVER_ERROR', message: 'Failed to update notification channel' });
      }
      return { success: true, id, updatedAt: Date.now() };
    }),

  /**
   * Delete a notification channel.
   */
  deleteNotificationChannel: adminProcedure
    .input(z.object({
      id: z.number(),
    }))
    .mutation(async ({ input }) => {
      const success = await deleteNotificationChannel(input.id);
      if (!success) {
        throw new TRPCError({ code: 'INTERNAL_SERVER_ERROR', message: 'Failed to delete notification channel' });
      }
      return { success: true, id: input.id, deletedAt: Date.now() };
    }),

  // ─── Session Replay Procedures ──────────────────────────────────────

  /**
   * Get detailed session information for replay viewer.
   */
  getSessionDetail: adminProcedure
    .input(z.object({
      sessionId: z.string(),
    }))
    .query(async ({ input }) => {
      const db = await getDb();
      if (!db) throw new TRPCError({ code: 'INTERNAL_SERVER_ERROR', message: 'Database not available' });

      // Get session
      const [session] = await db
        .select()
        .from(geometrySessions)
        .where(eq(geometrySessions.sessionId, input.sessionId))
        .limit(1);

      if (!session) {
        throw new TRPCError({ code: 'NOT_FOUND', message: `Session not found: ${input.sessionId}` });
      }

      // Get all snapshots ordered by generation index
      const snapshots = await db
        .select()
        .from(geometrySnapshots)
        .where(eq(geometrySnapshots.sessionId, input.sessionId))
        .orderBy(geometrySnapshots.generationIndex);

      // Get all events ordered by creation time
      const events = await db
        .select()
        .from(geometryEvents)
        .where(eq(geometryEvents.sessionId, input.sessionId))
        .orderBy(geometryEvents.createdAt);

      // Compute snapshot diffs (compare consecutive snapshots)
      const snapshotDiffs = snapshots.map((snap, i) => {
        if (i === 0) return { index: snap.generationIndex, diffs: [] as string[] };
        const prev = snapshots[i - 1];
        const diffs: string[] = [];

        if (snap.fixationRisk !== prev.fixationRisk) {
          const delta = snap.fixationRisk - prev.fixationRisk;
          diffs.push(`fixationRisk: ${prev.fixationRisk.toFixed(4)} → ${snap.fixationRisk.toFixed(4)} (${delta >= 0 ? '+' : ''}${delta.toFixed(4)})`);
        }
        if (snap.driftScore !== prev.driftScore) {
          const delta = snap.driftScore - prev.driftScore;
          diffs.push(`driftScore: ${prev.driftScore.toFixed(4)} → ${snap.driftScore.toFixed(4)} (${delta >= 0 ? '+' : ''}${delta.toFixed(4)})`);
        }
        if (snap.stabilityClass !== prev.stabilityClass) {
          diffs.push(`stabilityClass: ${prev.stabilityClass} → ${snap.stabilityClass}`);
        }
        if (snap.shouldConstrain !== prev.shouldConstrain) {
          diffs.push(`shouldConstrain: ${prev.shouldConstrain} → ${snap.shouldConstrain}`);
        }
        if (snap.loopDetected !== prev.loopDetected) {
          diffs.push(`loopDetected: ${prev.loopDetected} → ${snap.loopDetected}`);
        }
        if (snap.singularityDetected !== prev.singularityDetected) {
          diffs.push(`singularityDetected: ${prev.singularityDetected} → ${snap.singularityDetected}`);
        }
        if (snap.phaseTransitionDetected !== prev.phaseTransitionDetected) {
          diffs.push(`phaseTransitionDetected: ${prev.phaseTransitionDetected} → ${snap.phaseTransitionDetected}`);
        }
        if (snap.entropyDelta !== null && prev.entropyDelta !== null && snap.entropyDelta !== prev.entropyDelta) {
          diffs.push(`entropyDelta: ${prev.entropyDelta.toFixed(4)} → ${snap.entropyDelta.toFixed(4)}`);
        }
        if (snap.curvatureDelta !== null && prev.curvatureDelta !== null && snap.curvatureDelta !== prev.curvatureDelta) {
          diffs.push(`curvatureDelta: ${prev.curvatureDelta.toFixed(4)} → ${snap.curvatureDelta.toFixed(4)}`);
        }

        return { index: snap.generationIndex, diffs };
      });

      return {
        session,
        snapshots,
        events,
        snapshotDiffs,
        timeline: buildTimeline(snapshots, events),
      };
    }),

  /**
   * Set the neurocosmology advanced runtime mode.
   */
  setNeuroMode: adminProcedure
    .input(z.object({
      mode: z.enum(['off', 'shadow', 'telemetry', 'advisory', 'active']),
    }))
    .mutation(async ({ input }) => {
      try {
        setAdvancedRuntimeMode(input.mode as AdvancedRuntimeMode);
        return { success: true, mode: input.mode, updatedAt: Date.now() };
      } catch (error) {
        const message = error instanceof Error ? error.message : String(error);
        log.error({ mode: input.mode, error: message }, 'Failed to set neuro mode');
        throw new TRPCError({ code: 'BAD_REQUEST', message: `Failed to set mode: ${message}` });
      }
    }),

  // ─── Test Alert Trigger ──────────────────────────────────────────

  /**
   * Fire a simulated test alert through the full pipeline.
   * Useful for testing notification channels and escalation policies.
   */
  fireTestAlert: adminProcedure
    .input(z.object({
      alertType: z.enum([
        'high_fixation_risk', 'high_drift_score', 'high_loop_rate',
        'singularity_burst', 'phase_transition_burst',
        'invariant_violation_accumulation', 'compute_degradation',
      ]),
      channelId: z.number().optional(), // Specific channel to test
    }))
    .mutation(async ({ input }) => {
      log.info({ alertType: input.alertType, channelId: input.channelId }, 'Firing test alert');

      // Build synthetic metrics that will trigger the specified alert type
      const syntheticPre = {
        fixationRisk: input.alertType === 'high_fixation_risk' ? 0.95 : 0.1,
        driftScore: input.alertType === 'high_drift_score' ? 0.95 : 0.1,
        loopDetected: input.alertType === 'high_loop_rate',
        singularityDetected: input.alertType === 'singularity_burst',
        phaseTransition: input.alertType === 'phase_transition_burst',
        invariantViolations: input.alertType === 'invariant_violation_accumulation' ? 15 : 0,
      };

      const syntheticPost = {
        computeTimeMs: input.alertType === 'compute_degradation' ? 500 : 10,
        postComputeTimeMs: input.alertType === 'compute_degradation' ? 500 : 5,
      };

      try {
        const result = await evaluateAlerts(
          syntheticPre as any,
          syntheticPost as any,
          `test_session_${Date.now()}`,
        );

        return {
          success: true,
          alertsFired: result.alertsFired,
          message: result.alertsFired > 0
            ? `Test alert fired successfully (${result.alertsFired} alert(s))`
            : 'Alert was suppressed (check if enabled and cooldown is active)',
          timestamp: Date.now(),
        };
      } catch (error) {
        const message = error instanceof Error ? error.message : String(error);
        log.error({ alertType: input.alertType, error: message }, 'Test alert failed');
        throw new TRPCError({ code: 'INTERNAL_SERVER_ERROR', message: `Test alert failed: ${message}` });
      }
    }),

  // ─── Escalation Policy Management ───────────────────────────────

  /**
   * Get all escalation policies.
   */
  getEscalationPolicies: adminProcedure
    .query(async () => {
      return await getEscalationPolicies();
    }),

  /**
   * Create a new escalation policy.
   */
  createEscalationPolicy: adminProcedure
    .input(z.object({
      name: z.string().min(1).max(128),
      enabled: z.boolean().optional(),
      alertTypes: z.array(z.string()).optional(),
      fromSeverity: z.enum(['warning', 'critical']).optional(),
      escalationAfterMs: z.number().min(60000).max(86400000).optional(), // 1min to 24h
      escalateToSeverity: z.enum(['warning', 'critical']).optional(),
      escalateToChannels: z.array(z.number()).optional(),
      maxEscalations: z.number().min(1).max(10).optional(),
    }))
    .mutation(async ({ input }) => {
      const id = await createEscalationPolicy(input);
      return { success: true, id, name: input.name };
    }),

  /**
   * Update an existing escalation policy.
   */
  updateEscalationPolicy: adminProcedure
    .input(z.object({
      id: z.number(),
      name: z.string().min(1).max(128).optional(),
      enabled: z.boolean().optional(),
      alertTypes: z.array(z.string()).optional(),
      fromSeverity: z.enum(['warning', 'critical']).optional(),
      escalationAfterMs: z.number().min(60000).max(86400000).optional(),
      escalateToSeverity: z.enum(['warning', 'critical']).optional(),
      escalateToChannels: z.array(z.number()).optional(),
      maxEscalations: z.number().min(1).max(10).optional(),
    }))
    .mutation(async ({ input }) => {
      const { id, ...updates } = input;
      const success = await updateEscalationPolicy(id, updates);
      return { success };
    }),

  /**
   * Delete an escalation policy.
   */
  deleteEscalationPolicy: adminProcedure
    .input(z.object({ id: z.number() }))
    .mutation(async ({ input }) => {
      const success = await deleteEscalationPolicy(input.id);
      return { success };
    }),

  /**
   * Get escalation history.
   */
  getEscalationHistory: adminProcedure
    .input(z.object({
      alertId: z.string().optional(),
      limit: z.number().min(1).max(200).default(50),
    }).optional())
    .query(async ({ input }) => {
      return await getEscalationHistory(input?.alertId, input?.limit ?? 50);
    }),

  /**
   * Manually trigger an escalation check cycle.
   */
  runEscalationCheck: adminProcedure
    .mutation(async () => {
      const escalated = await runEscalationCheck();
      return {
        success: true,
        escalatedCount: escalated.length,
        events: escalated,
        engineRunning: isEscalationEngineRunning(),
      };
    }),

  /**
   * Get SSE connection stats.
   */
  getSSEStats: adminProcedure
    .query(() => {
      return {
        connectedClients: getSSEClientCount(),
        engineRunning: isEscalationEngineRunning(),
        timestamp: Date.now(),
      };
    }),

  // ─── Alert Analytics ──────────────────────────────────────────

  /**
   * Get alert frequency by type over a date range (time-series data for charts).
   */
  getAlertFrequency: adminProcedure
    .input(z.object({
      days: z.number().min(1).max(365).default(7),
      alertTypes: z.array(z.string()).optional(),
    }).optional())
    .query(async ({ input }) => {
      return getAlertFrequencyByType({
        days: input?.days ?? 7,
        alertTypes: input?.alertTypes,
      });
    }),

  /**
   * Get comprehensive alert summary statistics.
   */
  getAlertSummaryStats: adminProcedure
    .input(z.object({
      days: z.number().min(1).max(365).default(30),
    }).optional())
    .query(async ({ input }) => {
      return getAlertSummaryStats(input?.days ?? 30);
    }),

  // ─── Incident Management ──────────────────────────────────────

  /**
   * Get incidents with optional filtering.
   */
  getIncidents: adminProcedure
    .input(z.object({
      status: z.enum(['open', 'acknowledged', 'resolved']).optional(),
      alertType: z.string().optional(),
      severity: z.enum(['warning', 'critical']).optional(),
      days: z.number().min(1).max(365).optional(),
      limit: z.number().min(1).max(200).default(50),
      offset: z.number().min(0).default(0),
    }).optional())
    .query(async ({ input }) => {
      return getIncidents(input ?? undefined);
    }),

  /**
   * Get incident detail with all grouped alerts.
   */
  getIncidentDetail: adminProcedure
    .input(z.object({ incidentId: z.string() }))
    .query(async ({ input }) => {
      const detail = await getIncidentDetail(input.incidentId);
      if (!detail) {
        throw new TRPCError({ code: 'NOT_FOUND', message: 'Incident not found' });
      }
      return detail;
    }),

  /**
   * Acknowledge an incident.
   */
  acknowledgeIncident: adminProcedure
    .input(z.object({ incidentId: z.string() }))
    .mutation(async ({ input }) => {
      const success = await acknowledgeIncident(input.incidentId);
      return { success };
    }),

  /**
   * Resolve an incident with optional notes.
   */
  resolveIncident: adminProcedure
    .input(z.object({
      incidentId: z.string(),
      resolvedBy: z.string().default('admin'),
      notes: z.string().optional(),
    }))
    .mutation(async ({ input }) => {
      const success = await resolveIncident(input.incidentId, input.resolvedBy, input.notes);
      return { success };
    }),
});

// ─── Helper Functions ──────────────────────────────────────────────

interface TimelineEntry {
  timestamp: number;
  type: 'snapshot' | 'event';
  generationIndex: number | null;
  label: string;
  severity?: string;
  data: Record<string, unknown>;
}

/**
 * Build a unified timeline from snapshots and events for the replay viewer.
 * Merges both data sources into a single chronological list.
 */
function buildTimeline(
  snapshots: Array<{ createdAt: Date; generationIndex: number; fixationRisk: number; driftScore: number; stabilityClass: string; shouldConstrain: boolean; loopDetected: boolean | null; singularityDetected: boolean | null; phaseTransitionDetected: boolean | null; entropyDelta: number | null; curvatureDelta: number | null; preComputeTimeMs: number; postComputeTimeMs: number | null }>,
  events: Array<{ createdAt: Date; eventType: string; severity: string; message: string | null; generationIndex: number | null; metadata: Record<string, unknown> | null }>,
): TimelineEntry[] {
  const timeline: TimelineEntry[] = [];

  // Add snapshots
  for (const snap of snapshots) {
    timeline.push({
      timestamp: new Date(snap.createdAt).getTime(),
      type: 'snapshot',
      generationIndex: snap.generationIndex,
      label: `Gen #${snap.generationIndex}: fixation=${(snap.fixationRisk * 100).toFixed(1)}%, drift=${(snap.driftScore * 100).toFixed(1)}%, stability=${snap.stabilityClass}`,
      data: {
        fixationRisk: snap.fixationRisk,
        driftScore: snap.driftScore,
        stabilityClass: snap.stabilityClass,
        shouldConstrain: snap.shouldConstrain,
        loopDetected: snap.loopDetected,
        singularityDetected: snap.singularityDetected,
        phaseTransitionDetected: snap.phaseTransitionDetected,
        entropyDelta: snap.entropyDelta,
        curvatureDelta: snap.curvatureDelta,
        computeTimeMs: snap.preComputeTimeMs + (snap.postComputeTimeMs ?? 0),
      },
    });
  }

  // Add events
  for (const event of events) {
    timeline.push({
      timestamp: new Date(event.createdAt).getTime(),
      type: 'event',
      generationIndex: event.generationIndex,
      label: event.message ?? event.eventType,
      severity: event.severity,
      data: {
        eventType: event.eventType,
        severity: event.severity,
        metadata: event.metadata,
      },
    });
  }

  // Sort chronologically
  timeline.sort((a, b) => a.timestamp - b.timestamp);

  return timeline;
}

