  /**
   * Get overview stats for the geometry dashboard header cards.
   */
  getOverview: adminProcedure
    .input(z.object({
      timeRangeHours: z.number().min(1).max(720).default(24),
    }).optional())
    .query(async ({ input }) => {
      const db = await getDb();
      if (!db) throw new TRPCError({ code: 'INTERNAL_SERVER_ERROR', message: 'Database not available' });
      const hours = input?.timeRangeHours ?? 24;
      const since = new Date(Date.now() - hours * 60 * 60 * 1000);

      const [sessionStats] = await db
        .select({
          totalSessions: count(),
          avgFixation: avg(geometrySessions.avgFixationRisk),
          avgDrift: avg(geometrySessions.avgDriftScore),
          maxFixation: max(geometrySessions.maxFixationRisk),
          maxDrift: max(geometrySessions.maxDriftScore),
          avgCompute: avg(geometrySessions.avgComputeTimeMs),
        })
        .from(geometrySessions)
        .where(gte(geometrySessions.createdAt, since));

      const [snapshotStats] = await db
        .select({
          totalGenerations: count(),
          constraintsInjected: sql<number>`SUM(CASE WHEN ${geometrySnapshots.shouldConstrain} = true THEN 1 ELSE 0 END)`,
          loopsDetected: sql<number>`SUM(CASE WHEN ${geometrySnapshots.loopDetected} = true THEN 1 ELSE 0 END)`,
          singularities: sql<number>`SUM(CASE WHEN ${geometrySnapshots.singularityDetected} = true THEN 1 ELSE 0 END)`,
          phaseTransitions: sql<number>`SUM(CASE WHEN ${geometrySnapshots.phaseTransitionDetected} = true THEN 1 ELSE 0 END)`,
        })
        .from(geometrySnapshots)
        .where(gte(geometrySnapshots.createdAt, since));

      const [eventStats] = await db
        .select({
          totalEvents: count(),
          criticalEvents: sql<number>`SUM(CASE WHEN ${geometryEvents.severity} = 'critical' THEN 1 ELSE 0 END)`,
          warningEvents: sql<number>`SUM(CASE WHEN ${geometryEvents.severity} = 'warning' THEN 1 ELSE 0 END)`,
        })
        .from(geometryEvents)
        .where(gte(geometryEvents.createdAt, since));

      return {
        timeRangeHours: hours,
        sessions: {
          total: sessionStats?.totalSessions ?? 0,
          avgFixationRisk: Number(sessionStats?.avgFixation ?? 0),
          avgDriftScore: Number(sessionStats?.avgDrift ?? 0),
          maxFixationRisk: Number(sessionStats?.maxFixation ?? 0),
          maxDriftScore: Number(sessionStats?.maxDrift ?? 0),
          avgComputeTimeMs: Number(sessionStats?.avgCompute ?? 0),
        },
        generations: {
          total: snapshotStats?.totalGenerations ?? 0,
          constraintsInjected: Number(snapshotStats?.constraintsInjected ?? 0),
          loopsDetected: Number(snapshotStats?.loopsDetected ?? 0),
          singularities: Number(snapshotStats?.singularities ?? 0),
          phaseTransitions: Number(snapshotStats?.phaseTransitions ?? 0),
        },
        events: {
          total: eventStats?.totalEvents ?? 0,
          critical: Number(eventStats?.criticalEvents ?? 0),
          warnings: Number(eventStats?.warningEvents ?? 0),
        },
        metrics: getGeometryMetrics(),
      };
    }),

  /**
   * List geometry sessions with pagination.
   */
  listSessions: adminProcedure
    .input(z.object({
      limit: z.number().min(1).max(100).default(20),
      offset: z.number().min(0).default(0),
      status: z.enum(["active", "completed", "error"]).optional(),
    }).optional())
    .query(async ({ input }) => {
      const db = await getDb();
      if (!db) throw new TRPCError({ code: 'INTERNAL_SERVER_ERROR', message: 'Database not available' });
      const limit = input?.limit ?? 20;
      const offset = input?.offset ?? 0;
      const status = input?.status;

      const conditions = status ? [eq(geometrySessions.status, status)] : [];

      const sessions = await db
        .select()
        .from(geometrySessions)
        .where(conditions.length > 0 ? and(...conditions) : undefined)
        .orderBy(desc(geometrySessions.createdAt))
        .limit(limit)
        .offset(offset);

      const [{ total }] = await db
        .select({ total: count() })
        .from(geometrySessions)
        .where(conditions.length > 0 ? and(...conditions) : undefined);

      return { sessions, total, limit, offset };
    }),

