  /**
   * Diagnostic: trigger a live governed generation through the full geometry pipeline.
   * Returns the complete audit trail showing pre-hook → post-hook → metrics recording.
   */
  diagnosticGeneration: adminProcedure
    .input(z.object({
      prompt: z.string().min(1).max(500).default('What is emotional intelligence and why does it matter?'),
      currentState: z.record(z.string(), z.number()).optional(),
    }).optional())
    .mutation(async ({ input, ctx }) => {
      const startTime = performance.now();
      const auditTrail: string[] = [];
      const flags = getFlags();
      const mode = getRuntimeMode();
      const advancedDiag = getAdvancedFlagDiagnostics();

      auditTrail.push(`[CONFIG] Runtime: ${flags.GEOMETRY_RUNTIME_ENABLED ? 'ENABLED' : 'DISABLED'}, Mode: ${mode}`);
      auditTrail.push(`[CONFIG] Flags: ${JSON.stringify(flags)}`);
      auditTrail.push(`[CONFIG] Neuro advanced: ${advancedDiag.enabled ? 'ENABLED' : 'DISABLED'}, Mode: ${advancedDiag.mode}`);

      const testState = input?.currentState ?? {
        emotionalMass: 5.0,
        emotionalCharge: 0.3,
        emotionalDistance: 2.0,
        attentionCurvature: 1.5,
        memoryEntropy: 0.7,
        emotionalEnergy: 12.5,
        subconscious_density: 0.4,
        recurrenceCount: 3,
        topicDiversity: 0.6,
        emotionalValence: 0.2,
        arousalLevel: 0.5,
        coherenceScore: 0.8,
      };

      // Step 1: Pre-generation hook
      let preResult;
      try {
        preResult = await preGenerationHook({
          sessionId: `diag_${Date.now()}`,
          userId: `admin-${ctx.user.id}`,
          prompt: input?.prompt ?? 'What is emotional intelligence and why does it matter?',
          currentState: testState,
        });
        auditTrail.push(`[PRE-HOOK] Hash: ${preResult.preStateHash}, Fixation: ${preResult.fixationRisk.toFixed(4)}, Drift: ${preResult.driftScore.toFixed(4)}, Stability: ${preResult.stabilityClass}, Eigen: ${preResult.eigenClassification}, Constrain: ${preResult.shouldConstrain}, Time: ${preResult.computeTimeMs.toFixed(2)}ms`);
        if (preResult.constraintsInjected.length > 0) {
          auditTrail.push(`[PRE-HOOK] Constraints: ${preResult.constraintsInjected.join(', ')}`);
        }
        // Record metrics
        recordPreHook(
          preResult.fixationRisk,
          preResult.driftScore,
          preResult.computeTimeMs,
          preResult.shouldConstrain,
          preResult.constraintsInjected.length,
        );
        auditTrail.push(`[METRICS] Pre-hook metrics recorded`);
      } catch (err) {
        auditTrail.push(`[PRE-HOOK] FAILED: ${err instanceof Error ? err.message : String(err)}`);
        preResult = createSafeDefaults();
      }

      // Step 2: Advanced neurocosmology pre-hook
      try {
        const advPre = await advancedPreGenerationHook({
          currentState: testState,
          stateHistory: [],
        });
        if (advPre.enabled) {
          auditTrail.push(`[NEURO-PRE] Mode: ${advPre.mode}, Singularity: ${advPre.singularity?.isSingularity ?? false}, PhaseShift: ${advPre.phaseTransition?.isPhaseShift ?? false}, Invariants: ${advPre.invariantReport?.violations?.length ?? 0}, Time: ${advPre.computeTimeMs.toFixed(2)}ms`);
        } else {
          auditTrail.push(`[NEURO-PRE] Disabled (mode: ${advPre.mode})`);
        }
      } catch (err) {
        auditTrail.push(`[NEURO-PRE] FAILED (non-blocking): ${err instanceof Error ? err.message : String(err)}`);
      }

      // Step 3: Simulate LLM output (we don't actually call LLM in diagnostic mode)
      const simulatedOutput = 'Emotional intelligence is the ability to recognize, understand, and manage our own emotions while also being able to recognize, understand, and influence the emotions of others. It matters because it affects our relationships, decision-making, and overall well-being.';
      auditTrail.push(`[LLM] Simulated output (${simulatedOutput.length} chars) — diagnostic mode does not call real LLM`);

      // Step 4: Post-generation hook
      let postResult;
      try {
        postResult = await postGenerationHook({
          sessionId: `diag_${Date.now()}`,
          output: simulatedOutput,
          preResult,
        });
        auditTrail.push(`[POST-HOOK] Hash: ${postResult.postStateHash}, EntropyΔ: ${postResult.entropyDelta.toFixed(4)}, CurvatureΔ: ${postResult.curvatureDelta.toFixed(4)}, Loop: ${postResult.loopDetected}, Time: ${postResult.computeTimeMs.toFixed(2)}ms`);
        // Record metrics
        recordPostHook(postResult.computeTimeMs, postResult.loopDetected);
        auditTrail.push(`[METRICS] Post-hook metrics recorded`);
      } catch (err) {
        auditTrail.push(`[POST-HOOK] FAILED: ${err instanceof Error ? err.message : String(err)}`);
      }

      // Step 5: Advanced neurocosmology post-hook
      try {
        const advPost = await advancedPostGenerationHook({
          updatedState: testState,
          stateHistory: [],
        });
        if (advPost.enabled) {
          auditTrail.push(`[NEURO-POST] Singularity: ${advPost.singularity?.isSingularity ?? false}, PhaseShift: ${advPost.phaseTransition?.isPhaseShift ?? false}, Invariants: ${advPost.invariantReport?.violations?.length ?? 0}, Time: ${advPost.computeTimeMs.toFixed(2)}ms`);
        } else {
          auditTrail.push(`[NEURO-POST] Disabled (mode: ${advPost.mode})`);
        }
      } catch (err) {
        auditTrail.push(`[NEURO-POST] FAILED (non-blocking): ${err instanceof Error ? err.message : String(err)}`);
      }

      const totalTimeMs = performance.now() - startTime;
      const metricsAfter = getGeometryMetrics();
      auditTrail.push(`[COMPLETE] Total diagnostic time: ${totalTimeMs.toFixed(2)}ms`);

      return {
        success: true,
        totalTimeMs,
        preResult,
        postResult: postResult ?? null,
        metricsAfter,
        auditTrail,
        config: {
          geometryFlags: flags,
          runtimeMode: mode,
          neurocosmology: advancedDiag,
        },
      };
    }),

