      const history = await getAlertHistoryFromDb({
        alertType: input?.alertType as AlertType | undefined,
        severity: input?.severity as AlertSeverity | undefined,
        acknowledged: input?.acknowledged,
        limit: input?.limit ?? 50,
      });
      const summary = getAlertSummary();
      return { history, summary };
    }),

  /**
   * Acknowledge an alert by ID.
   */
  acknowledgeAlert: adminProcedure
    .input(z.object({
      alertId: z.string(),
    }))
    .mutation(async ({ input, ctx }) => {
      const success = await acknowledgeAlertPersistent(input.alertId, `admin-${ctx.user.id}`);
      if (!success) {
        throw new TRPCError({ code: 'NOT_FOUND', message: `Alert not found: ${input.alertId}` });
      }
      return { success: true, alertId: input.alertId, acknowledgedAt: Date.now() };
    }),

  /**
   * Get count of unacknowledged alerts (lightweight polling for sidebar badge).
   */
  getUnacknowledgedCount: adminProcedure
    .query(async () => {
      const count = await getUnacknowledgedCount();
      return { count };
    }),

  // ─── Notification Channel Management ──────────────────────────────

  /**
   * List all notification channels.
   */
  getNotificationChannels: adminProcedure
    .query(async () => {
      return await getNotificationChannels();
    }),

  /**
   * Create a new notification channel.
   */
  createNotificationChannel: adminProcedure
    .input(z.object({
      name: z.string().min(1).max(128),
      channelType: z.enum(['owner', 'slack', 'email']),
      enabled: z.boolean().default(true),
      config: z.object({
        webhookUrl: z.string().url().optional(),
        emailTo: z.string().email().optional(),
        emailFrom: z.string().email().optional(),
      }).optional(),
      alertTypes: z.array(z.string()).optional(),
      minSeverity: z.enum(['warning', 'critical']).default('warning'),
    }))
    .mutation(async ({ input }) => {
      const id = await createNotificationChannel(input);
      return { success: true, id, createdAt: Date.now() };
    }),

  /**
   * Update an existing notification channel.
   */
  updateNotificationChannel: adminProcedure
    .input(z.object({
      id: z.number(),
      name: z.string().min(1).max(128).optional(),
      enabled: z.boolean().optional(),
      config: z.object({
        webhookUrl: z.string().url().optional(),
        emailTo: z.string().email().optional(),
        emailFrom: z.string().email().optional(),
      }).optional(),
      alertTypes: z.array(z.string()).optional(),
      minSeverity: z.enum(['warning', 'critical']).optional(),
    }))
    .mutation(async ({ input }) => {
      const { id, ...updates } = input;
      const success = await updateNotificationChannel(id, updates);
      if (!success) {
        throw new TRPCError({ code: 'INTERNAL_SERVER_ERROR', message: 'Failed to update notification channel' });
      }
      return { success: true, id, updatedAt: Date.now() };
    }),

  /**
   * Delete a notification channel.
   */
  deleteNotificationChannel: adminProcedure
    .input(z.object({
      id: z.number(),
    }))
    .mutation(async ({ input }) => {
      const success = await deleteNotificationChannel(input.id);
      if (!success) {
        throw new TRPCError({ code: 'INTERNAL_SERVER_ERROR', message: 'Failed to delete notification channel' });
      }
      return { success: true, id: input.id, deletedAt: Date.now() };
    }),

  // ─── Session Replay Procedures ──────────────────────────────────────

  /**
   * Get detailed session information for replay viewer.
   */
  getSessionDetail: adminProcedure
    .input(z.object({
      sessionId: z.string(),
    }))
    .query(async ({ input }) => {
      const db = await getDb();
      if (!db) throw new TRPCError({ code: 'INTERNAL_SERVER_ERROR', message: 'Database not available' });

      // Get session
      const [session] = await db
        .select()
        .from(geometrySessions)
        .where(eq(geometrySessions.sessionId, input.sessionId))
        .limit(1);

      if (!session) {
        throw new TRPCError({ code: 'NOT_FOUND', message: `Session not found: ${input.sessionId}` });
      }

      // Get all snapshots ordered by generation index
      const snapshots = await db
        .select()
        .from(geometrySnapshots)
        .where(eq(geometrySnapshots.sessionId, input.sessionId))
        .orderBy(geometrySnapshots.generationIndex);

      // Get all events ordered by creation time
      const events = await db
        .select()
        .from(geometryEvents)
        .where(eq(geometryEvents.sessionId, input.sessionId))
        .orderBy(geometryEvents.createdAt);

      // Compute snapshot diffs (compare consecutive snapshots)
      const snapshotDiffs = snapshots.map((snap, i) => {
        if (i === 0) return { index: snap.generationIndex, diffs: [] as string[] };
        const prev = snapshots[i - 1];
        const diffs: string[] = [];

        if (snap.fixationRisk !== prev.fixationRisk) {
          const delta = snap.fixationRisk - prev.fixationRisk;
          diffs.push(`fixationRisk: ${prev.fixationRisk.toFixed(4)} → ${snap.fixationRisk.toFixed(4)} (${delta >= 0 ? '+' : ''}${delta.toFixed(4)})`);
        }
        if (snap.driftScore !== prev.driftScore) {
          const delta = snap.driftScore - prev.driftScore;
          diffs.push(`driftScore: ${prev.driftScore.toFixed(4)} → ${snap.driftScore.toFixed(4)} (${delta >= 0 ? '+' : ''}${delta.toFixed(4)})`);
        }
        if (snap.stabilityClass !== prev.stabilityClass) {
          diffs.push(`stabilityClass: ${prev.stabilityClass} → ${snap.stabilityClass}`);
        }
        if (snap.shouldConstrain !== prev.shouldConstrain) {
          diffs.push(`shouldConstrain: ${prev.shouldConstrain} → ${snap.shouldConstrain}`);
        }
        if (snap.loopDetected !== prev.loopDetected) {
          diffs.push(`loopDetected: ${prev.loopDetected} → ${snap.loopDetected}`);
        }
        if (snap.singularityDetected !== prev.singularityDetected) {
          diffs.push(`singularityDetected: ${prev.singularityDetected} → ${snap.singularityDetected}`);
        }
        if (snap.phaseTransitionDetected !== prev.phaseTransitionDetected) {
          diffs.push(`phaseTransitionDetected: ${prev.phaseTransitionDetected} → ${snap.phaseTransitionDetected}`);
        }
        if (snap.entropyDelta !== null && prev.entropyDelta !== null && snap.entropyDelta !== prev.entropyDelta) {
          diffs.push(`entropyDelta: ${prev.entropyDelta.toFixed(4)} → ${snap.entropyDelta.toFixed(4)}`);
        }
        if (snap.curvatureDelta !== null && prev.curvatureDelta !== null && snap.curvatureDelta !== prev.curvatureDelta) {
          diffs.push(`curvatureDelta: ${prev.curvatureDelta.toFixed(4)} → ${snap.curvatureDelta.toFixed(4)}`);
        }

        return { index: snap.generationIndex, diffs };
      });

      return {
        session,
        snapshots,
        events,
        snapshotDiffs,
        timeline: buildTimeline(snapshots, events),
      };
    }),

  /**
   * Set the neurocosmology advanced runtime mode.
   */
  setNeuroMode: adminProcedure
    .input(z.object({
      mode: z.enum(['off', 'shadow', 'telemetry', 'advisory', 'active']),
    }))
    .mutation(async ({ input }) => {
      try {
        setAdvancedRuntimeMode(input.mode as AdvancedRuntimeMode);
        return { success: true, mode: input.mode, updatedAt: Date.now() };
      } catch (error) {
        const message = error instanceof Error ? error.message : String(error);
        log.error({ mode: input.mode, error: message }, 'Failed to set neuro mode');
        throw new TRPCError({ code: 'BAD_REQUEST', message: `Failed to set mode: ${message}` });
      }
    }),

  // ─── Test Alert Trigger ──────────────────────────────────────────

  /**
   * Fire a simulated test alert through the full pipeline.
   * Useful for testing notification channels and escalation policies.
   */
  fireTestAlert: adminProcedure
    .input(z.object({
      alertType: z.enum([
        'high_fixation_risk', 'high_drift_score', 'high_loop_rate',
        'singularity_burst', 'phase_transition_burst',
        'invariant_violation_accumulation', 'compute_degradation',
      ]),
      channelId: z.number().optional(), // Specific channel to test
    }))
    .mutation(async ({ input }) => {
      log.info({ alertType: input.alertType, channelId: input.channelId }, 'Firing test alert');

      // Build synthetic metrics that will trigger the specified alert type
      const syntheticPre = {
        fixationRisk: input.alertType === 'high_fixation_risk' ? 0.95 : 0.1,
        driftScore: input.alertType === 'high_drift_score' ? 0.95 : 0.1,
        loopDetected: input.alertType === 'high_loop_rate',
        singularityDetected: input.alertType === 'singularity_burst',
        phaseTransition: input.alertType === 'phase_transition_burst',
        invariantViolations: input.alertType === 'invariant_violation_accumulation' ? 15 : 0,
      };

      const syntheticPost = {
        computeTimeMs: input.alertType === 'compute_degradation' ? 500 : 10,
        postComputeTimeMs: input.alertType === 'compute_degradation' ? 500 : 5,
      };

      try {
        const result = await evaluateAlerts(
          syntheticPre as any,
          syntheticPost as any,
          `test_session_${Date.now()}`,
        );

        return {
          success: true,
          alertsFired: result.alertsFired,
          message: result.alertsFired > 0
            ? `Test alert fired successfully (${result.alertsFired} alert(s))`
            : 'Alert was suppressed (check if enabled and cooldown is active)',
          timestamp: Date.now(),
        };
      } catch (error) {
        const message = error instanceof Error ? error.message : String(error);
        log.error({ alertType: input.alertType, error: message }, 'Test alert failed');
        throw new TRPCError({ code: 'INTERNAL_SERVER_ERROR', message: `Test alert failed: ${message}` });
      }
    }),

  // ─── Escalation Policy Management ───────────────────────────────

  /**
   * Get all escalation policies.
   */
  getEscalationPolicies: adminProcedure
    .query(async () => {
      return await getEscalationPolicies();
    }),

  /**
   * Create a new escalation policy.
   */
  createEscalationPolicy: adminProcedure
    .input(z.object({
      name: z.string().min(1).max(128),
      enabled: z.boolean().optional(),
      alertTypes: z.array(z.string()).optional(),
      fromSeverity: z.enum(['warning', 'critical']).optional(),
      escalationAfterMs: z.number().min(60000).max(86400000).optional(), // 1min to 24h
      escalateToSeverity: z.enum(['warning', 'critical']).optional(),
      escalateToChannels: z.array(z.number()).optional(),
      maxEscalations: z.number().min(1).max(10).optional(),
    }))
    .mutation(async ({ input }) => {
      const id = await createEscalationPolicy(input);
      return { success: true, id, name: input.name };
    }),

  /**
   * Update an existing escalation policy.
   */
  updateEscalationPolicy: adminProcedure
    .input(z.object({
      id: z.number(),
      name: z.string().min(1).max(128).optional(),
      enabled: z.boolean().optional(),
      alertTypes: z.array(z.string()).optional(),
      fromSeverity: z.enum(['warning', 'critical']).optional(),
      escalationAfterMs: z.number().min(60000).max(86400000).optional(),
      escalateToSeverity: z.enum(['warning', 'critical']).optional(),
      escalateToChannels: z.array(z.number()).optional(),
      maxEscalations: z.number().min(1).max(10).optional(),
    }))
    .mutation(async ({ input }) => {
      const { id, ...updates } = input;
      const success = await updateEscalationPolicy(id, updates);
      return { success };
    }),

  /**
   * Delete an escalation policy.
   */
  deleteEscalationPolicy: adminProcedure
    .input(z.object({ id: z.number() }))
    .mutation(async ({ input }) => {
      const success = await deleteEscalationPolicy(input.id);
      return { success };
    }),

  /**
   * Get escalation history.
   */
  getEscalationHistory: adminProcedure
    .input(z.object({
      alertId: z.string().optional(),
      limit: z.number().min(1).max(200).default(50),
    }).optional())
    .query(async ({ input }) => {
      return await getEscalationHistory(input?.alertId, input?.limit ?? 50);
    }),

  /**
   * Manually trigger an escalation check cycle.
   */
  runEscalationCheck: adminProcedure
    .mutation(async () => {
      const escalated = await runEscalationCheck();
      return {
        success: true,
        escalatedCount: escalated.length,
        events: escalated,
        engineRunning: isEscalationEngineRunning(),
      };
    }),

  /**
   * Get SSE connection stats.
   */
  getSSEStats: adminProcedure
    .query(() => {
      return {
        connectedClients: getSSEClientCount(),
        engineRunning: isEscalationEngineRunning(),
        timestamp: Date.now(),
      };
    }),

  // ─── Alert Analytics ──────────────────────────────────────────

  /**
   * Get alert frequency by type over a date range (time-series data for charts).
   */
  getAlertFrequency: adminProcedure
    .input(z.object({
      days: z.number().min(1).max(365).default(7),
      alertTypes: z.array(z.string()).optional(),
    }).optional())
    .query(async ({ input }) => {
      return getAlertFrequencyByType({
        days: input?.days ?? 7,
        alertTypes: input?.alertTypes,
      });
    }),

  /**
   * Get comprehensive alert summary statistics.
   */
  getAlertSummaryStats: adminProcedure
    .input(z.object({
      days: z.number().min(1).max(365).default(30),
    }).optional())
    .query(async ({ input }) => {
      return getAlertSummaryStats(input?.days ?? 30);
    }),

  // ─── Incident Management ──────────────────────────────────────

  /**
   * Get incidents with optional filtering.
   */
  getIncidents: adminProcedure
    .input(z.object({
      status: z.enum(['open', 'acknowledged', 'resolved']).optional(),
      alertType: z.string().optional(),
      severity: z.enum(['warning', 'critical']).optional(),
      days: z.number().min(1).max(365).optional(),
      limit: z.number().min(1).max(200).default(50),
      offset: z.number().min(0).default(0),
    }).optional())
    .query(async ({ input }) => {
      return getIncidents(input ?? undefined);
    }),

  /**
   * Get incident detail with all grouped alerts.
   */
  getIncidentDetail: adminProcedure
    .input(z.object({ incidentId: z.string() }))
    .query(async ({ input }) => {
      const detail = await getIncidentDetail(input.incidentId);
      if (!detail) {
        throw new TRPCError({ code: 'NOT_FOUND', message: 'Incident not found' });
      }
      return detail;
    }),

  /**
   * Acknowledge an incident.
   */
  acknowledgeIncident: adminProcedure
    .input(z.object({ incidentId: z.string() }))
    .mutation(async ({ input }) => {
      const success = await acknowledgeIncident(input.incidentId);
      return { success };
    }),

  /**
   * Resolve an incident with optional notes.
   */
  resolveIncident: adminProcedure
    .input(z.object({
      incidentId: z.string(),
      resolvedBy: z.string().default('admin'),
      notes: z.string().optional(),
    }))
    .mutation(async ({ input }) => {
      const success = await resolveIncident(input.incidentId, input.resolvedBy, input.notes);
      return { success };
    }),
});

// ─── Helper Functions ──────────────────────────────────────────────

interface TimelineEntry {
  timestamp: number;
  type: 'snapshot' | 'event';
  generationIndex: number | null;
  label: string;
  severity?: string;
  data: Record<string, unknown>;
}

/**
 * Build a unified timeline from snapshots and events for the replay viewer.
 * Merges both data sources into a single chronological list.
 */
function buildTimeline(
  snapshots: Array<{ createdAt: Date; generationIndex: number; fixationRisk: number; driftScore: number; stabilityClass: string; shouldConstrain: boolean; loopDetected: boolean | null; singularityDetected: boolean | null; phaseTransitionDetected: boolean | null; entropyDelta: number | null; curvatureDelta: number | null; preComputeTimeMs: number; postComputeTimeMs: number | null }>,
  events: Array<{ createdAt: Date; eventType: string; severity: string; message: string | null; generationIndex: number | null; metadata: Record<string, unknown> | null }>,
): TimelineEntry[] {
  const timeline: TimelineEntry[] = [];

  // Add snapshots
  for (const snap of snapshots) {
    timeline.push({
      timestamp: new Date(snap.createdAt).getTime(),
      type: 'snapshot',
      generationIndex: snap.generationIndex,
      label: `Gen #${snap.generationIndex}: fixation=${(snap.fixationRisk * 100).toFixed(1)}%, drift=${(snap.driftScore * 100).toFixed(1)}%, stability=${snap.stabilityClass}`,
      data: {
        fixationRisk: snap.fixationRisk,
        driftScore: snap.driftScore,
        stabilityClass: snap.stabilityClass,
        shouldConstrain: snap.shouldConstrain,
        loopDetected: snap.loopDetected,
        singularityDetected: snap.singularityDetected,
        phaseTransitionDetected: snap.phaseTransitionDetected,
        entropyDelta: snap.entropyDelta,
        curvatureDelta: snap.curvatureDelta,
        computeTimeMs: snap.preComputeTimeMs + (snap.postComputeTimeMs ?? 0),
      },
    });
  }

  // Add events
  for (const event of events) {
    timeline.push({
      timestamp: new Date(event.createdAt).getTime(),
      type: 'event',
      generationIndex: event.generationIndex,
      label: event.message ?? event.eventType,
      severity: event.severity,
      data: {
        eventType: event.eventType,
        severity: event.severity,
        metadata: event.metadata,
      },
    });
  }

  // Sort chronologically
  timeline.sort((a, b) => a.timestamp - b.timestamp);

  return timeline;
}

