  // ─── Session Replay Procedures ──────────────────────────────────────

  /**
   * Get detailed session information for replay viewer.
   */
  getSessionDetail: adminProcedure
    .input(z.object({
      sessionId: z.string(),
    }))
    .query(async ({ input }) => {
      const db = await getDb();
      if (!db) throw new TRPCError({ code: 'INTERNAL_SERVER_ERROR', message: 'Database not available' });

      // Get session
      const [session] = await db
        .select()
        .from(geometrySessions)
        .where(eq(geometrySessions.sessionId, input.sessionId))
        .limit(1);

      if (!session) {
        throw new TRPCError({ code: 'NOT_FOUND', message: `Session not found: ${input.sessionId}` });
      }

      // Get all snapshots ordered by generation index
      const snapshots = await db
        .select()
        .from(geometrySnapshots)
        .where(eq(geometrySnapshots.sessionId, input.sessionId))
        .orderBy(geometrySnapshots.generationIndex);

      // Get all events ordered by creation time
      const events = await db
        .select()
        .from(geometryEvents)
        .where(eq(geometryEvents.sessionId, input.sessionId))
        .orderBy(geometryEvents.createdAt);

      // Compute snapshot diffs (compare consecutive snapshots)
      const snapshotDiffs = snapshots.map((snap, i) => {
        if (i === 0) return { index: snap.generationIndex, diffs: [] as string[] };
        const prev = snapshots[i - 1];
        const diffs: string[] = [];

        if (snap.fixationRisk !== prev.fixationRisk) {
          const delta = snap.fixationRisk - prev.fixationRisk;
          diffs.push(`fixationRisk: ${prev.fixationRisk.toFixed(4)} → ${snap.fixationRisk.toFixed(4)} (${delta >= 0 ? '+' : ''}${delta.toFixed(4)})`);
        }
        if (snap.driftScore !== prev.driftScore) {
          const delta = snap.driftScore - prev.driftScore;
          diffs.push(`driftScore: ${prev.driftScore.toFixed(4)} → ${snap.driftScore.toFixed(4)} (${delta >= 0 ? '+' : ''}${delta.toFixed(4)})`);
        }
        if (snap.stabilityClass !== prev.stabilityClass) {
          diffs.push(`stabilityClass: ${prev.stabilityClass} → ${snap.stabilityClass}`);
        }
        if (snap.shouldConstrain !== prev.shouldConstrain) {
          diffs.push(`shouldConstrain: ${prev.shouldConstrain} → ${snap.shouldConstrain}`);
        }
        if (snap.loopDetected !== prev.loopDetected) {
          diffs.push(`loopDetected: ${prev.loopDetected} → ${snap.loopDetected}`);
        }
        if (snap.singularityDetected !== prev.singularityDetected) {
          diffs.push(`singularityDetected: ${prev.singularityDetected} → ${snap.singularityDetected}`);
        }
        if (snap.phaseTransitionDetected !== prev.phaseTransitionDetected) {
          diffs.push(`phaseTransitionDetected: ${prev.phaseTransitionDetected} → ${snap.phaseTransitionDetected}`);
        }
        if (snap.entropyDelta !== null && prev.entropyDelta !== null && snap.entropyDelta !== prev.entropyDelta) {
          diffs.push(`entropyDelta: ${prev.entropyDelta.toFixed(4)} → ${snap.entropyDelta.toFixed(4)}`);
        }
        if (snap.curvatureDelta !== null && prev.curvatureDelta !== null && snap.curvatureDelta !== prev.curvatureDelta) {
          diffs.push(`curvatureDelta: ${prev.curvatureDelta.toFixed(4)} → ${snap.curvatureDelta.toFixed(4)}`);
        }

        return { index: snap.generationIndex, diffs };
      });

      return {
        session,
        snapshots,
        events,
        snapshotDiffs,
        timeline: buildTimeline(snapshots, events),
      };
    }),

