tool_use_result.originalFile:
/**
 * Geometry Admin Router — tRPC endpoints for the /admin/geometry dashboard.
 * 
 * Provides real-time and historical data for emotional geometry monitoring:
 * - Session listing with aggregate metrics
 * - Snapshot timeseries for longitudinal analysis
 * - Event timeline for alerts and interventions
 * - Live state from the runtime bridge
 * - Prometheus-style metrics export
 */

import { z } from 'zod';
import { TRPCError } from '@trpc/server';
import { createLogger } from '../_core/logger';

const log = createLogger('geometry-admin-router');
import { adminProcedure, router } from '../_core/trpc';
import { getDb } from '../db';
import { geometrySessions, geometrySnapshots, geometryEvents } from '../../drizzle/schema';
import { desc, eq, and, gte, count, avg, max, sql } from 'drizzle-orm';
import { createSafeDefaults, preGenerationHook, postGenerationHook, type GeometryPreGenerationResult, type GeometryPostGenerationResult } from '../emotional-geometry-runtime/geometry-runtime-bridge';
import { createInitialState, updateBaseDimensions, type CanonicalEmotionalState } from '../emotional-geometry-runtime/state/EmotionalState';
import { getGeometryMetrics, resetGeometryMetrics, recordPreHook, recordPostHook } from '../emotional-geometry-runtime/geometry-metrics';
import { getFlags, getRuntimeMode, setGeometryFlag, setGeometryRuntimeMode, type GeometryFeatureFlags, type GeometryRuntimeMode } from '../emotional-geometry-runtime/feature-flags';
import { advancedPreGenerationHook, advancedPostGenerationHook } from '../neurocosmology-runtime-advanced/integration-hooks';
import { getAdvancedFlagDiagnostics, getAdvancedFlags, getAdvancedRuntimeMode, setAdvancedFlag, setAdvancedRuntimeMode, type AdvancedFeatureFlags, type AdvancedRuntimeMode } from '../neurocosmology-runtime-advanced/feature-flags';
import { getAlertConfigs, getAlertConfig, setAlertThreshold, setAlertEnabled, setAlertCooldown, setAlertSeverity, resetAlertConfigs, getAlertHistory, getAlertHistoryFromDb, acknowledgeAlert, acknowledgeAlertPersistent, getAlertSummary, getUnacknowledgedCount, getNotificationChannels, createNotificationChannel, updateNotificationChannel, deleteNotificationChannel, evaluateAlerts, ALERT_TYPES, type AlertType, type AlertSeverity } from '../emotional-geometry-runtime/geometry-alerting';
import { getEscalationPolicies, createEscalationPolicy, updateEscalationPolicy, deleteEscalationPolicy, getEscalationHistory, runEscalationCheck, isEscalationEngineRunning, getSSEClientCount, type EscalationPolicyConfig } from '../emotional-geometry-runtime/escalation-engine';
import { getAlertFrequencyByType, getAlertSummaryStats, getIncidents, getIncidentDetail, resolveIncident, acknowledgeIncident } from '../emotional-geometry-runtime/alert-analytics';

export const geometryAdminRouter = router({
  // =========================================================================
  // NEUROCOSMOLOGY VALIDATION ENDPOINTS
  // =========================================================================

  /**
   * Get neurocosmology validation status — calibration state, recent runs,
   * proof bundles, registered backends.
   * Exposed at /admin/neurocosmology in the dashboard.
   */
  neurocosmologyStatus: adminProcedure
    .query(async () => {
      const { getNeurocosmologyStatus } = await import(
        '../emotional-geometry-runtime/validation/validationOrchestrator'
      );
      return getNeurocosmologyStatus();
    }),

  /**
   * Trigger a validation run (on-demand, not just nightly).
   * Requires at least 2 model backends configured via env vars.
   */
  triggerValidation: adminProcedure
    .input(z.object({
      modelIds: z.array(z.string()).optional(),
      stimuliSubset: z.array(z.string()).optional(),
      skipHumanCalibration: z.boolean().optional(),
    }).optional())
    .mutation(async ({ input }) => {
      const { runValidation } = await import(
        '../emotional-geometry-runtime/validation/validationOrchestrator'
      );
      return runValidation(input ?? undefined);
    }),

  /**
   * Get current calibration state (hot-path, in-memory).
   */
  calibrationState: adminProcedure
    .query(async () => {
      const { getCalibrationState } = await import(
        '../emotional-geometry-runtime/validation/calibrationMode'
      );
      return getCalibrationState();
    }),

  /**
   * Check whether field-driven boosts are currently active.
   */
  fieldBoostsActive: adminProcedure
    .query(async () => {
      const { areFieldBoostsActive } = await import(
        '../emotional-geometry-runtime/validation/calibrationMode'
      );
      return { active: areFieldBoostsActive() };
    }),

  /**
   * Get recent proof bundles for provenance audit.
   */
  proofBundles: adminProcedure
    .input(z.object({ limit: z.number().min(1).max(100).default(10) }).optional())
    .query(async ({ input }) => {
      const { getRecentProofBundles } = await import(
        '../emotional-geometry-runtime/validation/calibrationMode'
      );
      return getRecentProofBundles(input?.limit ?? 10);
    }),

  // =========================================================================
  // ORIGINAL GEOMETRY ADMIN ENDPOINTS
  // =========================================================================

  /**
   * Get overview stats for the geometry dashboard header cards.
   */
  getOverview: adminProcedure
    .input(z.object({
      timeRangeHours: z.number().min(1).max(720).default(24),
    }).optional())
    .query(async ({ input }) => {
      const db = await getDb();
      if (!db) throw new TRPCError({ code: 'INTERNAL_SERVER_ERROR', message: 'Database not available' });
      const hours = input?.timeRangeHours ?? 24;
      const since = new Date(Date.now() - hours * 60 * 60 * 1000);

      const [sessionStats] = await db
        .select({
          totalSessions: count(),
          avgFixation: avg(geometrySessions.avgFixationRisk),
          avgDrift: avg(geometrySessions.avgDriftScore),
          maxFixation: max(geometrySessions.maxFixationRisk),
          maxDrift: max(geometrySessions.maxDriftScore),
          avgCompute: avg(geometrySessions.avgComputeTimeMs),
        })
        .from(geometrySessions)
        .where(gte(geometrySessions.createdAt, since));

      const [snapshotStats] = await db
        .select({
          totalGenerations: count(),
          constraintsInjected: sql<number>`SUM(CASE WHEN ${geometrySnapshots.shouldConstrain} = true THEN 1 ELSE 0 END)`,
          loopsDetected: sql<number>`SUM(CASE WHEN ${geometrySnapshots.loopDetected} = true THEN 1 ELSE 0 END)`,
          singularities: sql<number>`SUM(CASE WHEN ${geometrySnapshots.singularityDetected} = true THEN 1 ELSE 0 END)`,
          phaseTransitions: sql<number>`SUM(CASE WHEN ${geometrySnapshots.phaseTransitionDetected} = true THEN 1 ELSE 0 END)`,
        })
        .from(geometrySnapshots)
        .where(gte(geometrySnapshots.createdAt, since));

      const [eventStats] = await db
        .select({
          totalEvents: count(),
          criticalEvents: sql<number>`SUM(CASE WHEN ${geometryEvents.severity} = 'critical' THEN 1 ELSE 0 END)`,
          warningEvents: sql<number>`SUM(CASE WHEN ${geometryEvents.severity} = 'warning' THEN 1 ELSE 0 END)`,
        })
        .from(geometryEvents)
        .where(gte(geometryEvents.createdAt, since));

      return {
        timeRangeHours: hours,
        sessions: {
          total: sessionStats?.totalSessions ?? 0,
          avgFixationRisk: Number(sessionStats?.avgFixation ?? 0),
          avgDriftScore: Number(sessionStats?.avgDrift ?? 0),
          maxFixationRisk: Number(sessionStats?.maxFixation ?? 0),
          maxDriftScore: Number(sessionStats?.maxDrift ?? 0),
          avgComputeTimeMs: Number(sessionStats?.avgCompute ?? 0),
        },
        generations: {
          total: snapshotStats?.totalGenerations ?? 0,
          constraintsInjected: Number(snapshotStats?.constraintsInjected ?? 0),
          loopsDetected: Number(snapshotStats?.loopsDetected ?? 0),
          singularities: Number(snapshotStats?.singularities ?? 0),
          phaseTransitions: Number(snapshotStats?.phaseTransitions ?? 0),
        },
        events: {
          total: eventStats?.totalEvents ?? 0,
          critical: Number(eventStats?.criticalEvents ?? 0),
          warnings: Number(eventStats?.warningEvents ?? 0),
        },
        metrics: getGeometryMetrics(),
      };
    }),

  /**
   * List geometry sessions with pagination.
   */
  listSessions: adminProcedure
    .input(z.object({
      limit: z.number().min(1).max(100).default(20),
      offset: z.number().min(0).default(0),
      status: z.enum(["active", "completed", "error"]).optional(),
    }).optional())
    .query(async ({ input }) => {
      const db = await getDb();
      if (!db) throw new TRPCError({ code: 'INTERNAL_SERVER_ERROR', message: 'Database not available' });
      const limit = input?.limit ?? 20;
      const offset = input?.offset ?? 0;
      const status = input?.status;

      const conditions = status ? [eq(geometrySessions.status, status)] : [];

      const sessions = await db
        .select()
        .from(geometrySessions)
        .where(conditions.length > 0 ? and(...conditions) : undefined)
        .orderBy(desc(geometrySessions.createdAt))
        .limit(limit)
        .offset(offset);

      const [{ total }] = await db
        .select({ total: count() })
        .from(geometrySessions)
        .where(conditions.length > 0 ? and(...conditions) : undefined);

      return { sessions, total, limit, offset };
    }),

  /**
   * Get snapshots for a specific session (timeseries data).
   */
  getSessionSnapshots: adminProcedure
    .input(z.object({
      sessionId: z.string(),
      limit: z.number().min(1).max(500).default(100),
    }))
    .query(async ({ input }) => {
      const db = await getDb();
      if (!db) throw new TRPCError({ code: 'INTERNAL_SERVER_ERROR', message: 'Database not available' });
      const snapshots = await db
        .select()
        .from(geometrySnapshots)
        .where(eq(geometrySnapshots.sessionId, input.sessionId))
        .orderBy(geometrySnapshots.generationIndex)
        .limit(input.limit);

      return { snapshots, sessionId: input.sessionId };
    }),

  /**
   * Get event timeline with filtering.
   */
  getEvents: adminProcedure
    .input(z.object({
      limit: z.number().min(1).max(200).default(50),
      offset: z.number().min(0).default(0),
      eventType: z.string().optional(),
      severity: z.enum(["info", "warning", "critical"]).optional(),
      sessionId: z.string().optional(),
      timeRangeHours: z.number().min(1).max(720).default(24),
    }).optional())
    .query(async ({ input }) => {
      const db = await getDb();
      if (!db) throw new TRPCError({ code: 'INTERNAL_SERVER_ERROR', message: 'Database not available' });
      const limit = input?.limit ?? 50;
      const offset = input?.offset ?? 0;
      const since = new Date(Date.now() - (input?.timeRangeHours ?? 24) * 60 * 60 * 1000);

      const conditions = [gte(geometryEvents.createdAt, since)];
      if (input?.severity) conditions.push(eq(geometryEvents.severity, input.severity));
      if (input?.sessionId) conditions.push(eq(geometryEvents.sessionId, input.sessionId));

      const events = await db
        .select()
        .from(geometryEvents)
        .where(and(...conditions))
        .orderBy(desc(geometryEvents.createdAt))
        .limit(limit)
        .offset(offset);

      const [{ total }] = await db
        .select({ total: count() })
        .from(geometryEvents)
        .where(and(...conditions));

      return { events, total, limit, offset };
    }),

  /**
   * Get the current runtime state (live, not from DB).
   */
  getLiveState: adminProcedure
    .query(async () => {
      const safeDefaults = createSafeDefaults();
      const metrics = getGeometryMetrics();

      return {
        runtimeStatus: 'active',
        safeDefaults,
        metrics,
        timestamp: Date.now(),
      };
    }),

  /**
   * Get Prometheus-style metrics export.
   */
  getMetrics: adminProcedure
    .query(async () => {
      return getGeometryMetrics();
    }),

  /**
   * Reset metrics counters (admin action).
   */
  resetMetrics: adminProcedure
    .mutation(async () => {
      resetGeometryMetrics();
      return { success: true, resetAt: Date.now() };
    }),

  /**
   * Get stability distribution over time (for charts).
   */
  getStabilityDistribution: adminProcedure
    .input(z.object({
      timeRangeHours: z.number().min(1).max(720).default(24),
    }).optional())
    .query(async ({ input }) => {
      const db = await getDb();
      if (!db) throw new TRPCError({ code: 'INTERNAL_SERVER_ERROR', message: 'Database not available' });
      const since = new Date(Date.now() - (input?.timeRangeHours ?? 24) * 60 * 60 * 1000);

      const distribution = await db
        .select({
          stabilityClass: geometrySnapshots.stabilityClass,
          count: count(),
        })
        .from(geometrySnapshots)
        .where(gte(geometrySnapshots.createdAt, since))
        .groupBy(geometrySnapshots.stabilityClass);

      return { distribution, timeRangeHours: input?.timeRangeHours ?? 24 };
    }),

  /**
   * Diagnostic: trigger a live governed generation through the full geometry pipeline.
   * Returns the complete audit trail showing pre-hook → post-hook → metrics recording.
   */
  diagnosticGeneration: adminProcedure
    .input(z.object({
      prompt: z.string().min(1).max(500).default('What is emotional intelligence and why does it matter?'),
      currentState: z.record(z.string(), z.number()).optional(),
    }).optional())
    .mutation(async ({ input, ctx }) => {
      const startTime = performance.now();
      const auditTrail: string[] = [];
      const flags = getFlags();
      const mode = getRuntimeMode();
      const advancedDiag = getAdvancedFlagDiagnostics();

      auditTrail.push(`[CONFIG] Runtime: ${flags.GEOMETRY_RUNTIME_ENABLED ? 'ENABLED' : 'DISABLED'}, Mode: ${mode}`);
      auditTrail.push(`[CONFIG] Flags: ${JSON.stringify(flags)}`);
      auditTrail.push(`[CONFIG] Neuro advanced: ${advancedDiag.enabled ? 'ENABLED' : 'DISABLED'}, Mode: ${advancedDiag.mode}`);

      const testState = input?.currentState ?? {
        emotionalMass: 5.0,
        emotionalCharge: 0.3,
        emotionalDistance: 2.0,
        attentionCurvature: 1.5,
        memoryEntropy: 0.7,
        emotionalEnergy: 12.5,
        subconscious_density: 0.4,
        recurrenceCount: 3,
        topicDiversity: 0.6,
        emotionalValence: 0.2,
        arousalLevel: 0.5,
        coherenceScore: 0.8,
      };

      // Step 1: Pre-generation hook
      let preResult;
      try {
        preResult = await preGenerationHook({
          sessionId: `diag_${Date.now()}`,
          userId: `admin-${ctx.user.id}`,
          prompt: input?.prompt ?? 'What is emotional intelligence and why does it matter?',
          currentState: testState,
        });
        auditTrail.push(`[PRE-HOOK] Hash: ${preResult.preStateHash}, Fixation: ${preResult.fixationRisk.toFixed(4)}, Drift: ${preResult.driftScore.toFixed(4)}, Stability: ${preResult.stabilityClass}, Eigen: ${preResult.eigenClassification}, Constrain: ${preResult.shouldConstrain}, Time: ${preResult.computeTimeMs.toFixed(2)}ms`);
        if (preResult.constraintsInjected.length > 0) {
          auditTrail.push(`[PRE-HOOK] Constraints: ${preResult.constraintsInjected.join(', ')}`);
        }
        // Record metrics
        recordPreHook(
          preResult.fixationRisk,
          preResult.driftScore,
          preResult.computeTimeMs,
          preResult.shouldConstrain,
          preResult.constraintsInjected.length,
        );
        auditTrail.push(`[METRICS] Pre-hook metrics recorded`);
      } catch (err) {
        auditTrail.push(`[PRE-HOOK] FAILED: ${err instanceof Error ? err.message : String(err)}`);
        preResult = createSafeDefaults();
      }

      // Step 2: Advanced neurocosmology pre-hook
      try {
        const advPre = await advancedPreGenerationHook({
          currentState: buildCanonicalState(testState, `diag_${Date.now()}`, `admin-${ctx.user.id}`),
          stateHistory: [],
        });
        if (advPre.enabled) {
          auditTrail.push(`[NEURO-PRE] Mode: ${advPre.mode}, Singularity: ${advPre.singularity?.isSingularity ?? false}, PhaseShift: ${advPre.phaseTransition?.isPhaseShift ?? false}, Invariants: ${advPre.invariantReport?.violations?.length ?? 0}, Time: ${advPre.computeTimeMs.toFixed(2)}ms`);
        } else {
          auditTrail.push(`[NEURO-PRE] Disabled (mode: ${advPre.mode})`);
        }
      } catch (err) {
        auditTrail.push(`[NEURO-PRE] FAILED (non-blocking): ${err instanceof Error ? err.message : String(err)}`);
      }

      // Step 3: Simulate LLM output (we don't actually call LLM in diagnostic mode)
      const simulatedOutput = 'Emotional intelligence is the ability to recognize, understand, and manage our own emotions while also being able to recognize, understand, and influence the emotions of others. It matters because it affects our relationships, decision-making, and overall well-being.';
      auditTrail.push(`[LLM] Simulated output (${simulatedOutput.length} chars) — diagnostic mode does not call real LLM`);

      // Step 4: Post-generation hook
      let postResult;
      try {
        postResult = await postGenerationHook({
          sessionId: `diag_${Date.now()}`,
          output: simulatedOutput,
          preResult,
        });
        auditTrail.push(`[POST-HOOK] Hash: ${postResult.postStateHash}, EntropyΔ: ${postResult.entropyDelta.toFixed(4)}, CurvatureΔ: ${postResult.curvatureDelta.toFixed(4)}, Loop: ${postResult.loopDetected}, Time: ${postResult.computeTimeMs.toFixed(2)}ms`);
        // Record metrics
        recordPostHook(postResult.computeTimeMs, postResult.loopDetected);
        auditTrail.push(`[METRICS] Post-hook metrics recorded`);
      } catch (err) {
        auditTrail.push(`[POST-HOOK] FAILED: ${err instanceof Error ? err.message : String(err)}`);
      }

      // Step 5: Advanced neurocosmology post-hook
      try {
        const advPost = await advancedPostGenerationHook({
          updatedState: buildCanonicalState(testState, `diag_${Date.now()}`, `admin-${ctx.user.id}`),
          stateHistory: [],
        });
        if (advPost.enabled) {
          auditTrail.push(`[NEURO-POST] Singularity: ${advPost.singularity?.isSingularity ?? false}, PhaseShift: ${advPost.phaseTransition?.isPhaseShift ?? false}, Invariants: ${advPost.invariantReport?.violations?.length ?? 0}, Time: ${advPost.computeTimeMs.toFixed(2)}ms`);
        } else {
          auditTrail.push(`[NEURO-POST] Disabled (mode: ${advPost.mode})`);
        }
      } catch (err) {
        auditTrail.push(`[NEURO-POST] FAILED (non-blocking): ${err instanceof Error ? err.message : String(err)}`);
      }

      const totalTimeMs = performance.now() - startTime;
      const metricsAfter = getGeometryMetrics();
      auditTrail.push(`[COMPLETE] Total diagnostic time: ${totalTimeMs.toFixed(2)}ms`);

      return {
        success: true,
        totalTimeMs,
        preResult,
        postResult: postResult ?? null,
        metricsAfter,
        auditTrail,
        config: {
          geometryFlags: flags,
          runtimeMode: mode,
          neurocosmology: advancedDiag,
        },
      };
    }),

  /**
