      days: z.number().min(1).max(365).optional(),
      limit: z.number().min(1).max(200).default(50),
      offset: z.number().min(0).default(0),
    }).optional())
    .query(async ({ input }) => {
      return getIncidents(input ?? undefined);
    }),

  /**
   * Get incident detail with all grouped alerts.
   */
  getIncidentDetail: adminProcedure
    .input(z.object({ incidentId: z.string() }))
    .query(async ({ input }) => {
      const detail = await getIncidentDetail(input.incidentId);
      if (!detail) {
        throw new TRPCError({ code: 'NOT_FOUND', message: 'Incident not found' });
      }
      return detail;
    }),

  /**
   * Acknowledge an incident.
   */
  acknowledgeIncident: adminProcedure
    .input(z.object({ incidentId: z.string() }))
    .mutation(async ({ input }) => {
      const success = await acknowledgeIncident(input.incidentId);
      return { success };
    }),

  /**
   * Resolve an incident with optional notes.
   */
  resolveIncident: adminProcedure
    .input(z.object({
      incidentId: z.string(),
      resolvedBy: z.string().default('admin'),
      notes: z.string().optional(),
    }))
    .mutation(async ({ input }) => {
      const success = await resolveIncident(input.incidentId, input.resolvedBy, input.notes);
      return { success };
    }),
});

// ─── Helper Functions ──────────────────────────────────────────────

interface TimelineEntry {
  timestamp: number;
  type: 'snapshot' | 'event';
  generationIndex: number | null;
  label: string;
  severity?: string;
  data: Record<string, unknown>;
}

/**
 * Build a unified timeline from snapshots and events for the replay viewer.
 * Merges both data sources into a single chronological list.
 */
function buildTimeline(
  snapshots: Array<{ createdAt: Date; generationIndex: number; fixationRisk: number; driftScore: number; stabilityClass: string; shouldConstrain: boolean; loopDetected: boolean | null; singularityDetected: boolean | null; phaseTransitionDetected: boolean | null; entropyDelta: number | null; curvatureDelta: number | null; preComputeTimeMs: number; postComputeTimeMs: number | null }>,
  events: Array<{ createdAt: Date; eventType: string; severity: string; message: string | null; generationIndex: number | null; metadata: Record<string, unknown> | null }>,
): TimelineEntry[] {
  const timeline: TimelineEntry[] = [];

  // Add snapshots
  for (const snap of snapshots) {
    timeline.push({
      timestamp: new Date(snap.createdAt).getTime(),
      type: 'snapshot',
      generationIndex: snap.generationIndex,
      label: `Gen #${snap.generationIndex}: fixation=${(snap.fixationRisk * 100).toFixed(1)}%, drift=${(snap.driftScore * 100).toFixed(1)}%, stability=${snap.stabilityClass}`,
      data: {
        fixationRisk: snap.fixationRisk,
        driftScore: snap.driftScore,
        stabilityClass: snap.stabilityClass,
        shouldConstrain: snap.shouldConstrain,
        loopDetected: snap.loopDetected,
        singularityDetected: snap.singularityDetected,
        phaseTransitionDetected: snap.phaseTransitionDetected,
        entropyDelta: snap.entropyDelta,
        curvatureDelta: snap.curvatureDelta,
        computeTimeMs: snap.preComputeTimeMs + (snap.postComputeTimeMs ?? 0),
      },
    });
  }

  // Add events
  for (const event of events) {
    timeline.push({
      timestamp: new Date(event.createdAt).getTime(),
      type: 'event',
      generationIndex: event.generationIndex,
      label: event.message ?? event.eventType,
      severity: event.severity,
      data: {
        eventType: event.eventType,
        severity: event.severity,
        metadata: event.metadata,
      },
    });
  }

  // Sort chronologically
  timeline.sort((a, b) => a.timestamp - b.timestamp);

  return timeline;
}

